import type { LiturgyBlock } from '../types';

export const blocks: readonly LiturgyBlock[] = [
  {"id": "cu-str-0001", "section": "service", "who": "reader", "text": "ВО СВЯТУЮ И ВЕЛИКУЮ СУББОТУ НА УТРЕНИ"},
  {"id": "cu-str-0002", "section": "service", "who": "rubric", "text": "клеплет ко Утрени в седмый час нощи. Начинаем Утреню по обычаю. И по шестопсалмии ектения великая."},
  {"id": "cu-str-0003", "section": "service", "who": "reader", "text": "На Бог Господь: тропарь, глас 2:"},
  {"id": "cu-str-0004", "section": "service", "who": "reader", "text": "Благообразный Иосиф, / с древа снем Пречистое Тело Твое, / плащаницею чистою обвив, / и вонями во гробе нове покрыв положи."},
  {"id": "cu-str-0005", "section": "service", "who": "reader", "text": "Слава: Егда снизшел еси к смерти, Животе безсмертный, / тогда ад умертвил еси блистанием Божества. / Егда же и умершия от преисподних воскресил еси, / вся силы небесныя взываху: / Жизнодавче Христе Боже наш, слава Тебе."},
  {"id": "cu-str-0006", "section": "service", "who": "reader", "text": "И ныне: Мироносицам женам, при гробе представ Ангел вопияше: / мира мертвым суть прилична, / Христос же истления явися чуждь."},
  {"id": "cu-str-0007", "section": "service", "who": "rubric", "text": "И, кадящу священнику весь храм, начинаем пети Непорочны со сладкопением, такожде по коемуждо стисе и похвалы."},
  {"id": "cu-str-0008", "section": "service", "who": "reader", "text": "Статия первая."},
  {"id": "cu-str-0009", "section": "service", "who": "rubric", "text": "Возглашает певец, во глас 5:"},
  {"id": "cu-str-0010", "section": "service", "who": "reader", "text": "Благословен еси, Господи, научи мя оправданием Твоим."},
  {"id": "cu-str-0011", "section": "service", "who": "reader", "text": "1 Блажени непорочнии в путь, / ходящии в законе Господни."},
  {"id": "cu-str-0012", "section": "service", "who": "reader", "text": "И похвалы, во глас 5:"},
  {"id": "cu-str-0013", "section": "service", "who": "reader", "text": "Жизнь во гробе положился еси, Христе, / и Ангельская воинства ужасахуся, снизхождение славяще Твое."},
  {"id": "cu-str-0014", "section": "service", "who": "reader", "text": "2 Блажени испытающии свидения Его, / всем сердцем взыщут Его."},
  {"id": "cu-str-0015", "section": "service", "who": "reader", "text": "Животе, како умираеши? / Како и во гробе обитаеши, / смерти же царство разрушаеши, / и от ада мертвыя возставляеши?"},
  {"id": "cu-str-0016", "section": "service", "who": "reader", "text": "3 Не делающии бо беззакония / в путех Его ходиша."},
  {"id": "cu-str-0017", "section": "service", "who": "reader", "text": "Величаем Тя, Иисусе Царю, / и чтим погребение и страдания Твоя, / имиже спасл еси нас от истления."},
  {"id": "cu-str-0018", "section": "service", "who": "reader", "text": "4 Ты заповедал еси заповеди Твоя / сохранити зело."},
  {"id": "cu-str-0019", "section": "service", "who": "reader", "text": "Меры земли положивый, / в малом обитаеши, Иисусе Всецарю, гробе днесь, / от гробов мертвыя возставляяй."},
  {"id": "cu-str-0020", "section": "service", "who": "reader", "text": "5 Дабы исправилися путие мои, / сохранити оправдания Твоя."},
  {"id": "cu-str-0021", "section": "service", "who": "reader", "text": "Иисусе Христе мой, Царю всех, / что ища к сущим во аде пришел еси? / Или род отрешити человеческий?"},
  {"id": "cu-str-0022", "section": "service", "who": "reader", "text": "6 Тогда не постыжуся, / внегда призрети ми на вся заповеди Твоя."},
  {"id": "cu-str-0023", "section": "service", "who": "reader", "text": "Владыка всех зрится мертв, / и во гробе новем полагается, / истощивый гробы мертвых."},
  {"id": "cu-str-0024", "section": "service", "who": "reader", "text": "7 Исповемся Тебе в правости сердца, / внегда научити ми ся судьбам правды Твоея."},
  {"id": "cu-str-0025", "section": "service", "who": "reader", "text": "Животе, во гробе положился еси, Христе, / и смертию Твоею смерть погубил еси, / и источил еси мирови жизнь."},
  {"id": "cu-str-0026", "section": "service", "who": "reader", "text": "8 Оправдания Твоя сохраню, / не остави мене до зела."},
  {"id": "cu-str-0027", "section": "service", "who": "reader", "text": "Со злодеи яко злодей, Христе, вменился еси, / оправдая нас всех от злодейства древняго запинателя."},
  {"id": "cu-str-0028", "section": "service", "who": "reader", "text": "9 В чесом исправит юнейший путь свой? / Внегда сохранити словеса Твоя."},
  {"id": "cu-str-0029", "section": "service", "who": "reader", "text": "Красный добротою паче всех человек, / яко беззрачен мертв является, / естество украсивый всех."},
  {"id": "cu-str-0030", "section": "service", "who": "reader", "text": "10 Всем сердцем моим взысках Тебе, / не отрини мене от заповедей Твоих."},
  {"id": "cu-str-0031", "section": "service", "who": "reader", "text": "Ад како стерпит, Спасе, пришествие Твое, / а не паче болезнует омрачаемь, / блистания света Твоего зарею ослеплен?"},
  {"id": "cu-str-0032", "section": "service", "who": "reader", "text": "11 В сердце моем скрых словеса Твоя, / яко да не согрешу Тебе."},
  {"id": "cu-str-0033", "section": "service", "who": "reader", "text": "Иисусе, сладкий мой, и спасительный Свете, / во гробе како темнем скрылся еси? / О несказаннаго и неизреченнаго терпения!"},
  {"id": "cu-str-0034", "section": "service", "who": "reader", "text": "12 Благословен еси, Господи, / научи мя оправданием Твоим."},
  {"id": "cu-str-0035", "section": "service", "who": "reader", "text": "Недоумевает и естество умное, и множество безплотное, Христе, / таинства несказаннаго и неизреченнаго Твоего погребения."},
  {"id": "cu-str-0036", "section": "service", "who": "reader", "text": "13 Устнама моима возвестих / вся судьбы уст Твоих."},
  {"id": "cu-str-0037", "section": "service", "who": "reader", "text": "О чудес странных! / О вещей новых! / Дыхания моего Податель бездыханен носится, / погребаемь рукама Иосифовыма."},
  {"id": "cu-str-0038", "section": "service", "who": "reader", "text": "14 На пути свидений Твоих насладихся, / яко о всяком богатстве."},
  {"id": "cu-str-0039", "section": "service", "who": "reader", "text": "И во гроб зашел еси, / и недр, Христе, Отеческих никакоже отлучился еси: / сие странное и преславное купно."},
  {"id": "cu-str-0040", "section": "service", "who": "reader", "text": "15 В заповедех Твоих поглумлюся, / и уразумею пути Твоя."},
  {"id": "cu-str-0041", "section": "service", "who": "reader", "text": "Истинный небесе и земли Царь, / аще и во гробе малейшем заключился еси, / познался еси всей твари, Иисусе."},
  {"id": "cu-str-0042", "section": "service", "who": "reader", "text": "16 Во оправданиих Твоих поучуся, / не забуду словес Твоих."},
  {"id": "cu-str-0043", "section": "service", "who": "reader", "text": "Тебе положену во гробе, Создателю Христе, / адская подвизашася основания, / и гроби отверзошася человеков."},
  {"id": "cu-str-0044", "section": "service", "who": "reader", "text": "17 Воздаждь рабу Твоему, живи мя, / и сохраню словеса Твоя."},
  {"id": "cu-str-0045", "section": "service", "who": "reader", "text": "Землю содержай дланию, / умерщвлен плотию, под землею ныне содержится, / мертвыя избавляя адова содержания."},
  {"id": "cu-str-0046", "section": "service", "who": "reader", "text": "18 Открый очи мои, / и уразумею чудеса от закона Твоего."},
  {"id": "cu-str-0047", "section": "service", "who": "reader", "text": "Из истления возшел еси, Животе Спасе мой, / тебе умершу, и к мертвым пришедшу, / и сломившу адовы вереи."},
  {"id": "cu-str-0048", "section": "service", "who": "reader", "text": "19 Пришлец аз есмь на земли, / не скрый от мене заповеди Твоя."},
  {"id": "cu-str-0049", "section": "service", "who": "reader", "text": "Якоже света светильник, / ныне плоть Божия, под землю яко под спуд крыется, / и отгоняет сущую во аде тьму."},
  {"id": "cu-str-0050", "section": "service", "who": "reader", "text": "20 Возлюби, душа моя, / возжелати судьбы Твоя на всякое время."},
  {"id": "cu-str-0051", "section": "service", "who": "reader", "text": "Умных стекается воинств множество со Иосифом и Никодимом, / погребсти Тя, Невместимаго во гробе мале."},
  {"id": "cu-str-0052", "section": "service", "who": "reader", "text": "21 Запретил еси гордым, / прокляти уклоняющиися от заповедей Твоих."},
  {"id": "cu-str-0053", "section": "service", "who": "reader", "text": "Умерщвлен волею, и положен под землею, / жизноточне Иисусе мой, / оживил еси умерщвлена мя преступлением горьким."},
  {"id": "cu-str-0054", "section": "service", "who": "reader", "text": "22 Отыми от мене понос и уничижение, / яко свидений Твоих взысках."},
  {"id": "cu-str-0055", "section": "service", "who": "reader", "text": "Изменяшеся вся тварь страстию Твоею, / вся бо Тебе, Слове, сострадаху, / Содержителя Тя ведуща всех."},
  {"id": "cu-str-0056", "section": "service", "who": "reader", "text": "23 Ибо седоша князи, и на мя клеветаху: / раб же Твой глумляшеся во оправданиих Твоих."},
  {"id": "cu-str-0057", "section": "service", "who": "reader", "text": "Живота камень во чреве прием, / ад всеядец, изблева, / от века яже поглоти мертвыя."},
  {"id": "cu-str-0058", "section": "service", "who": "reader", "text": "24 Ибо свидения Твоя поучение мое есть, / и совети мои оправдания Твоя."},
  {"id": "cu-str-0059", "section": "service", "who": "reader", "text": "Во гробе нове положился еси, Христе, / и естество человеческое обновил еси, / воскрес боголепно из мертвых."},
  {"id": "cu-str-0060", "section": "service", "who": "reader", "text": "25 Прильпе земли душа моя, / живи мя по словеси Твоему."},
  {"id": "cu-str-0061", "section": "service", "who": "reader", "text": "На землю сшел еси, да спасеши Адама, / и на земли не обрет сего, Владыко, / даже до ада снизшел еси ищяй."},
  {"id": "cu-str-0062", "section": "service", "who": "reader", "text": "26 Пути моя возвестих, и услышал мя еси, / научи мя оправданием Твоим."},
  {"id": "cu-str-0063", "section": "service", "who": "reader", "text": "Сотрясеся страхом, Слове, вся земля, / и денница лучи скры, / величайшему в землисокровенному Твоему Свету."},
  {"id": "cu-str-0064", "section": "service", "who": "reader", "text": "27 Путь оправданий Твоих вразуми ми, / и поглумлюся в чудесех Твоих."},
  {"id": "cu-str-0065", "section": "service", "who": "reader", "text": "Яко человек убо умираеши волею, Спасе, / яко Бог же смертныя возставил еси от гробов, / и глубины греховныя."},
  {"id": "cu-str-0066", "section": "service", "who": "reader", "text": "28 Воздрема душа моя от уныния, / утверди мя в словесех Твоих."},
  {"id": "cu-str-0067", "section": "service", "who": "reader", "text": "Слезоточная рыдания, на Тебе Чистая / матерски, о Иисусе, накрапляющи вопияше: / како погребу Тя, Сыне?"},
  {"id": "cu-str-0068", "section": "service", "who": "reader", "text": "29 Путь неправды отстави от мене, / и законом Твоим помилуй мя."},
  {"id": "cu-str-0069", "section": "service", "who": "reader", "text": "Якоже пшеничное зерно, / зашед в недра земная, / многоперстный воздал еси клас, / возставив человеки, яже от Адама."},
  {"id": "cu-str-0070", "section": "service", "who": "reader", "text": "30 Путь истины изволих, / и судьбы Твоя не забых."},
  {"id": "cu-str-0071", "section": "service", "who": "reader", "text": "Под землею скрылся еси, яко солнце ныне, / и нощию смертною покровен был еси, / но возсияй светлейше Спасе."},
  {"id": "cu-str-0072", "section": "service", "who": "reader", "text": "31 Прилепихся свидением Твоим, Господи, / не посрами мене."},
  {"id": "cu-str-0073", "section": "service", "who": "reader", "text": "Якоже солнечный круг луна, Спасе, сокрывает, / и Тебе ныне гроб скры, / скончавшагося смертию плотски."},
  {"id": "cu-str-0074", "section": "service", "who": "reader", "text": "32 Путь заповедей Твоих текох, / егда разширил еси сердце мое."},
  {"id": "cu-str-0075", "section": "service", "who": "reader", "text": "Живот смерти вкусивый Христос, / от смерти смертныя свободи, / и всем ныне дарует живот."},
  {"id": "cu-str-0076", "section": "service", "who": "reader", "text": "33 Законоположи мне, Господи, путь оправданий Твоих, / и взыщу и выну."},
  {"id": "cu-str-0077", "section": "service", "who": "reader", "text": "Умерщвлена древле Адама завистно, / возводиши к животу умерщвлением Твоим, / Новый, Спасе, во плоти явлейся Адам."},
  {"id": "cu-str-0078", "section": "service", "who": "reader", "text": "34 Вразуми мя, и испытаю закон Твой, / и сохраню и всем сердцем моим."},
  {"id": "cu-str-0079", "section": "service", "who": "reader", "text": "Умнии Тя чини, простерта мертва зряще нас ради, / ужасахуся, покрываеми крилы, Спасе."},
  {"id": "cu-str-0080", "section": "service", "who": "reader", "text": "35 Настави мя на стезю заповедей Твоих, / яко тую восхотех."},
  {"id": "cu-str-0081", "section": "service", "who": "reader", "text": "Снем Тя, Слове, от древа мертва, / во гробе Иосиф ныне положи, / но востани, спасаяй вся, яко Бог."},
  {"id": "cu-str-0082", "section": "service", "who": "reader", "text": "36 Приклони сердце мое во свидения Твоя, / а не в лихоимство."},
  {"id": "cu-str-0083", "section": "service", "who": "reader", "text": "Ангельская, Спасе, радость быв, / ныне и печали сим был еси виновен, / видимь плотию бездыханен мертв."},
  {"id": "cu-str-0084", "section": "service", "who": "reader", "text": "37 Отврати очи мои, еже не видети суеты, / в пути Твоем живи мя."},
  {"id": "cu-str-0085", "section": "service", "who": "reader", "text": "Вознеслся еси на древе, / и живущия человеки совозносиши: / под землею же быв, / лежащия под нею воскрешаеши."},
  {"id": "cu-str-0086", "section": "service", "who": "reader", "text": "38 Постави рабу Твоему / слово Твое в страх Твой."},
  {"id": "cu-str-0087", "section": "service", "who": "reader", "text": "Якоже лев, Спасе, уснув плотию, / яко некий скимен мертв возстаеши, / отложив старость плотскую."},
  {"id": "cu-str-0088", "section": "service", "who": "reader", "text": "39 Отыми поношение мое, еже непщевах, / яко судьбы Твоя благи."},
  {"id": "cu-str-0089", "section": "service", "who": "reader", "text": "В ребра прободен был еси, / ребро вземый Адамле, / от негоже Еву создал еси, / и источил еси токи чистительныя."},
  {"id": "cu-str-0090", "section": "service", "who": "reader", "text": "40 Се возжелах заповеди Твоя, / в правде Твоей живи мя."},
  {"id": "cu-str-0091", "section": "service", "who": "reader", "text": "Тайно убо древле жрется агнец: / Ты же яве жрен быв, Незлобиве, / всю тварь очистил еси, Спасе."},
  {"id": "cu-str-0092", "section": "service", "who": "reader", "text": "41 И да приидет на мя милость твоя, Господи, / спасение Твое по словеси Твоему."},
  {"id": "cu-str-0093", "section": "service", "who": "reader", "text": "Кто изречет образ страшный воистинну новый? / Владычествуяй бо тварию, / днесь страсть приемлет, и умирает нас ради."},
  {"id": "cu-str-0094", "section": "service", "who": "reader", "text": "42 И отвещаю поношающим ми слово, / яко уповах на словеса Твоя."},
  {"id": "cu-str-0095", "section": "service", "who": "reader", "text": "Живота Сокровище, како зрится мертв? / Ужасающеся Ангели взываху: / како же во гробе заключается Бог?"},
  {"id": "cu-str-0096", "section": "service", "who": "reader", "text": "43 И не отыми от уст моих словесе истинна до зела, / яко на судьбы Твоя уповах."},
  {"id": "cu-str-0097", "section": "service", "who": "reader", "text": "Копием прободеннаго, Спасе, из ребра Твоего, / живот животом из живота спасшаго мя искапаеши, / и живиши мя с ним."},
  {"id": "cu-str-0098", "section": "service", "who": "reader", "text": "44 И сохраню закон Твой выну / в век, и в век века."},
  {"id": "cu-str-0099", "section": "service", "who": "reader", "text": "Распростерт на древе, собрал еси человеки: / в ребра же прободен, / животочное всем оставление источаеши, Иисусе."},
  {"id": "cu-str-0100", "section": "service", "who": "reader", "text": "45 И хождах в широте, / яко заповеди Твоя взысках."},
  {"id": "cu-str-0101", "section": "service", "who": "reader", "text": "Благообразный Иосиф, Спасе, образует страшно, / и погребает Тя яко мертва благообразно, / и ужасается Твоего образа страшнаго."},
  {"id": "cu-str-0102", "section": "service", "who": "reader", "text": "46 И глаголах о свидениих Твоих пред цари, / и не стыдяхся."},
  {"id": "cu-str-0103", "section": "service", "who": "reader", "text": "Под землею хотением низшед яко мертв, / возводиши от земли к небесным, оттуду падшия, Иисусе."},
  {"id": "cu-str-0104", "section": "service", "who": "reader", "text": "47 И поучахся в заповедех Твоих, / яже возлюбих зело."},
  {"id": "cu-str-0105", "section": "service", "who": "reader", "text": "Аще и мертв виден был еси, но живый яко Бог, / возводиши от земли к небесным, оттуду падшия, Иисусе."},
  {"id": "cu-str-0106", "section": "service", "who": "reader", "text": "48 И воздвигох руце мои / к заповедем Твоим, яже возлюбих."},
  {"id": "cu-str-0107", "section": "service", "who": "reader", "text": "Аще и мертв виден был еси, но жив яко Бог, / умерщвленыя человеки оживил еси, / моего умертвив умертвителя."},
  {"id": "cu-str-0108", "section": "service", "who": "reader", "text": "48 И глумляхся / во оправданиих Твоих."},
  {"id": "cu-str-0109", "section": "service", "who": "reader", "text": "О радости оныя! / О многия сладости! / Ихже во аде наполнил еси, / во днах мрачных Свет возсияв."},
  {"id": "cu-str-0110", "section": "service", "who": "reader", "text": "49 Помяни словеса Твоя рабу Твоему, / ихже упование дал ми еси."},
  {"id": "cu-str-0111", "section": "service", "who": "reader", "text": "Покланяюся страсти, / воспеваю погребение, / величаю Твою державу, Человеколюбче, / имиже свободихся страстей тлетворных."},
  {"id": "cu-str-0112", "section": "service", "who": "reader", "text": "50 То мя утеши во смирении моем, / яко слово Твое живи мя."},
  {"id": "cu-str-0113", "section": "service", "who": "reader", "text": "На Тя меч обнажися, Христе, / и меч крепкаго убо притупляется, / меч же обращается едемский."},
  {"id": "cu-str-0114", "section": "service", "who": "reader", "text": "51 Гордии законопреступоваху до зела, / от закона же Твоего не уклонихся."},
  {"id": "cu-str-0115", "section": "service", "who": "reader", "text": "Агница Агнца зрящи в заколении, / острием прободаема рыдаше, / сподвигши и стадо вопити."},
  {"id": "cu-str-0116", "section": "service", "who": "reader", "text": "52 Помянух судьбы Твоя от века, Господи, / и утешихся."},
  {"id": "cu-str-0117", "section": "service", "who": "reader", "text": "Аще и во гробе погребаешися, / аще и во ад идеши, / но и гробы истощил еси, / и ад обнажил еси, Христе."},
  {"id": "cu-str-0118", "section": "service", "who": "reader", "text": "53 Печаль прият мя от грешник, / оставляющих закон Твой."},
  {"id": "cu-str-0119", "section": "service", "who": "reader", "text": "Волею снизшел еси, Спасе, под землю, / умерщвленыя человеки оживил еси, / и возвел еси во славе Отчей."},
  {"id": "cu-str-0120", "section": "service", "who": "reader", "text": "54 Пета бяху мне оправдания Твоя / на месте пришельствия моего."},
  {"id": "cu-str-0121", "section": "service", "who": "reader", "text": "Троицы Един во плоти, / нас ради поносную претерпе смерть, / ужасается же солнце, и трепещет земля."},
  {"id": "cu-str-0122", "section": "service", "who": "reader", "text": "55 Помянух в нощи имя Твое, Господи, / и сохраних закон Твой."},
  {"id": "cu-str-0123", "section": "service", "who": "reader", "text": "Яко от источника горькаго, / Иудова колена исчадия в рове положиша, / Питателя маннодавца Иисуса."},
  {"id": "cu-str-0124", "section": "service", "who": "reader", "text": "56 Сей бысть мне, / яко оправданий Твоих взысках."},
  {"id": "cu-str-0125", "section": "service", "who": "reader", "text": "Судия яко судимь пред Пилатом судиею, / и предста, и смертию неправедною осужден бысть, древом крестным."},
  {"id": "cu-str-0126", "section": "service", "who": "reader", "text": "57 Часть моя еси, Господи, / рех сохранити закон Твой."},
  {"id": "cu-str-0127", "section": "service", "who": "reader", "text": "Гордый Израилю, / убийственнии людие, / что пострадавше, Варавву свободисте, / и Спаса предасте кресту?"},
  {"id": "cu-str-0128", "section": "service", "who": "reader", "text": "58 Помолихся Лицу Твоему всем сердцем моим, / помилуй мя по словеси Твоему."},
  {"id": "cu-str-0129", "section": "service", "who": "reader", "text": "Рукою Твоею создавый Адама от земли, / того ради естеством был еси Человек, / и распялся еси волею Твоею."},
  {"id": "cu-str-0130", "section": "service", "who": "reader", "text": "59 Помыслих пути Твоя, / и возвратих нозе мои во свидения Твоя."},
  {"id": "cu-str-0131", "section": "service", "who": "reader", "text": "Послушав, Слове, Отца Твоего, / даже до ада лютаго сошел еси, / и воскресил еси род человеческий."},
  {"id": "cu-str-0132", "section": "service", "who": "reader", "text": "60 Уготовихся и не смутихся, / сохранити заповеди Твоя."},
  {"id": "cu-str-0133", "section": "service", "who": "reader", "text": "Увы Мне, Свете мира! / Увы Мне, свете Мой, / Иисусе Мой возжеленный! / Вопияше Дева, рыдающи горько."},
  {"id": "cu-str-0134", "section": "service", "who": "reader", "text": "61 Ужа грешник обязашеся мне, / и закона Твоего не забых."},
  {"id": "cu-str-0135", "section": "service", "who": "reader", "text": "Завистливии, убийственнии и гордии людие, / поне плащаницы и сударя самаго стыдятся, воскресшу Христу."},
  {"id": "cu-str-0136", "section": "service", "who": "reader", "text": "62 Полунощи востах исповедатися Тебе / о судьбах правды Твоея."},
  {"id": "cu-str-0137", "section": "service", "who": "reader", "text": "Прииди убо, скверный убийце учениче, / и нрав злобы твоея покажи ми, / имже был еси предатель Христов."},
  {"id": "cu-str-0138", "section": "service", "who": "reader", "text": "63 Причастник аз есмь всем боящимся Тебе, / и хранящим заповеди Твоя."},
  {"id": "cu-str-0139", "section": "service", "who": "reader", "text": "Яко человеколюбив некто притворяешися буе, и слепе, / всегубительнейший, неверный, Миро продавый на цене."},
  {"id": "cu-str-0140", "section": "service", "who": "reader", "text": "64 Милости Твоея Господи, исполнь земля, / оправданием Твоим научи мя."},
  {"id": "cu-str-0141", "section": "service", "who": "reader", "text": "Небеснаго Мира кую имел еси цену Многоценнаго; / кое приял еси противодостойное; / неистовство обрел еси, проклятейший сатано."},
  {"id": "cu-str-0142", "section": "service", "who": "reader", "text": "65 Благость сотворил еси с рабом Твоим, Господи, / по словеси Твоему."},
  {"id": "cu-str-0143", "section": "service", "who": "reader", "text": "Аще нищелюбец еси, / и о мире печалуеши истощаемом во очищение души, / како за злате продаеши Светозарна?"},
  {"id": "cu-str-0144", "section": "service", "who": "reader", "text": "66 Благости и наказанию, и разуму научи мя, / яко заповедем Твоим веровах."},
  {"id": "cu-str-0145", "section": "service", "who": "reader", "text": "О Божий Слове! / О радосте Моя! / Како претерплю тридневное Твое погребение? / Ныне терзаюся утробою матерски."},
  {"id": "cu-str-0146", "section": "service", "who": "reader", "text": "67 Прежде даже не смирити ми ся, аз прегреших, / сего ради слово Твое сохраних."},
  {"id": "cu-str-0147", "section": "service", "who": "reader", "text": "Кто даст Ми воду и слез источники, / Богоневестная Дева взываше, / да восплачу сладкаго Ми Иисуса?"},
  {"id": "cu-str-0148", "section": "service", "who": "reader", "text": "68 Благ еси Ты, Господи, / и благостию Твоею научи мя оправданием Твоим."},
  {"id": "cu-str-0149", "section": "service", "who": "reader", "text": "О горы и холми, и человеков множества! / Восплачитеся, и вся рыдайте со Мною, / Бога вашего Материю!"},
  {"id": "cu-str-0150", "section": "service", "who": "reader", "text": "69 Умножися на мя неправда гордых, / аз же всем сердцем моим испытаю заповеди Твоя."},
  {"id": "cu-str-0151", "section": "service", "who": "reader", "text": "Когда вижду Тя, Спасе, безлетнаго Света, / радость и сладость сердца Моего? / Дева горько вопияше."},
  {"id": "cu-str-0152", "section": "service", "who": "reader", "text": "70 Усырися яко млеко сердце их, / аз же закону Твоему поучихся."},
  {"id": "cu-str-0153", "section": "service", "who": "reader", "text": "Аще и яко камень Спасе, краесекомый, / Ты приял еси сечение, / но источил еси живую струю, / яко Источник сый жизни."},
  {"id": "cu-str-0154", "section": "service", "who": "reader", "text": "71 Благо мне, яко смирил мя еси, / яко да научуся оправданием Твоим."},
  {"id": "cu-str-0155", "section": "service", "who": "reader", "text": "Яко от источника единаго сугубою рекою / ребром Твоим изливающим напаяющеся, / безсмертную приобретаем жизнь."},
  {"id": "cu-str-0156", "section": "service", "who": "reader", "text": "72 Благ мне закон уст Твоих, / паче тысящ злата и сребра."},
  {"id": "cu-str-0157", "section": "service", "who": "reader", "text": "Волею явился еси Слове, во гробе мертв, но живеши, / и человеки, якоже предрекл еси, / воскресением Твоим, Спасе мой, воздвизаеши."},
  {"id": "cu-str-0158", "section": "service", "who": "reader", "text": "Слава: Воспеваем Слове, Тебе всех Бога, / со Отцем и Святым Твоим Духом, / и славим Божественное Твое погребение."},
  {"id": "cu-str-0159", "section": "service", "who": "reader", "text": "И ныне, Богородичен: Блажим Тя, Богородице Чистая, / и почитаем тридневное погребение / Сына Твоего и Бога нашего верно."},
  {"id": "cu-str-0160", "section": "service", "who": "rubric", "text": "И паки первый припев оба лика вкупе:"},
  {"id": "cu-str-0161", "section": "service", "who": "choir", "text": "Жизнь во гробе положился еси, Христе, / и Ангельская воинства ужасахуся, снизхождение славяще Твое."},
  {"id": "cu-str-0162", "section": "service", "who": "rubric", "text": "Таже ектения малая. И возглас на первую статию:"},
  {"id": "cu-str-0163", "section": "service", "who": "choir", "text": "Яко благословися Твое Имя, и прославися Твое Царство, Отца, и Сына, и Святаго Духа, ныне и присно, и во веки веков."},
  {"id": "cu-str-0164", "section": "service", "who": "rubric", "text": "И, покадив, начинает вторую статию."},
  {"id": "cu-str-0165", "section": "service", "who": "choir", "text": "Статия вторая."},
  {"id": "cu-str-0166", "section": "service", "who": "rubric", "text": "Начинает левый лик благочинно тропарь, во глас 5:"},
  {"id": "cu-str-0167", "section": "service", "who": "choir", "text": "Достойно есть / величати Тя Жизнодавца, / на Кресте руце простершаго, / и сокрушшаго державу вражию."},
  {"id": "cu-str-0168", "section": "service", "who": "choir", "text": "73 Руце Твои сотвористе мя, и создасте мя; / вразуми мя, и научуся заповедем Твоим."},
  {"id": "cu-str-0169", "section": "service", "who": "choir", "text": "Достойно есть / величати Тя, всех Зиждителя: / Твоими бо страданьми имамы безстрастие, / избавльшеся от тления."},
  {"id": "cu-str-0170", "section": "service", "who": "choir", "text": "74 Боящиися Тебе узрят мя и возвеселятся, / яко на словеса Твоя уповах."},
  {"id": "cu-str-0171", "section": "service", "who": "choir", "text": "Ужасеся земля, / и солнце Спасе скрыся, / Тебе Невечернему Свету Христе, / зашедшу во гробе плотски."},
  {"id": "cu-str-0172", "section": "service", "who": "choir", "text": "75 Разумех, Господи, яко правда судьбы Твоя, / и воистинну смирил мя еси."},
  {"id": "cu-str-0173", "section": "service", "who": "choir", "text": "Уснул еси, Христе, / естественноживотным сном во гробе, / и от тяжкаго сна греховнаго / воздвигл еси род человеческий."},
  {"id": "cu-str-0174", "section": "service", "who": "choir", "text": "76 Буди же милость Твоя, да утешит мя, / по словеси Твоему рабу Твоему."},
  {"id": "cu-str-0175", "section": "service", "who": "choir", "text": "Едина жен, кроме болезней родих Тя Чадо, / болезни же ныне терплю Страстию Твоею нестерпимыя, / глаголаше Чистая."},
  {"id": "cu-str-0176", "section": "service", "who": "choir", "text": "77 Да приидут мне щедроты Твоя, и жив буду, / яко закон Твой поучение мое есть."},
  {"id": "cu-str-0177", "section": "service", "who": "choir", "text": "Горе Тя Спасе, неразлучно со Отцем суща, / доле же мертва простерта на земли, / ужасаются зряще Серафими."},
  {"id": "cu-str-0178", "section": "service", "who": "choir", "text": "78 Да постыдятся гордии, яко неправедно беззаконноваша на мя, / аз же поглумлюся в заповедех Твоих."},
  {"id": "cu-str-0179", "section": "service", "who": "choir", "text": "Раздирается церковная завеса Твоим распятием, / покрывают светила Слове свет, / Тебе, скрывшуся Солнцу под землю."},
  {"id": "cu-str-0180", "section": "service", "who": "choir", "text": "79 Да обратят мя боящиися Тебе, / и ведящии свидения Твоя."},
  {"id": "cu-str-0181", "section": "service", "who": "choir", "text": "Земли изначала единем манием водрузивый круг, / бездыханен, яко человек зайде под землю: / ужаснися видением небо."},
  {"id": "cu-str-0182", "section": "service", "who": "choir", "text": "80 Буди сердце мое непорочно во оправданиих Твоих, / яко да не постыжуся."},
  {"id": "cu-str-0183", "section": "service", "who": "choir", "text": "Зашел еси под землю, рукою Твоею создавый человека, / да воздвигнеши от падения соборы человеческия всесильною державою."},
  {"id": "cu-str-0184", "section": "service", "who": "choir", "text": "81 Исчезает во спасение Твое душа моя, / на словеса Твоя уповах."},
  {"id": "cu-str-0185", "section": "service", "who": "choir", "text": "Плач священный приидите воспоим Христу умершему, / яко древле жены мироносицы, / да и радуйся услышим с ними."},
  {"id": "cu-str-0186", "section": "service", "who": "choir", "text": "82 Исчезоша очи мои в слово Твое, глаголюще: / когда утешиши мя?"},
  {"id": "cu-str-0187", "section": "service", "who": "choir", "text": "Миро воистинну еси Ты, Слове неистощимое: / темже Ти и мира приношаху, / яко мертву Живому, жены мироносицы."},
  {"id": "cu-str-0188", "section": "service", "who": "choir", "text": "83 Зане бых яко мех на слане, / оправданий Твоих не забых."},
  {"id": "cu-str-0189", "section": "service", "who": "choir", "text": "Адова убо погребен царствия, Христе, сокрушаеши, / смертию же смерть умерщвляеши, / и тления свобождаеши земнородныя."},
  {"id": "cu-str-0190", "section": "service", "who": "choir", "text": "84 Колико есть дней раба Твоего? / Когда сотвориши ми от гонящих мя суд?"},
  {"id": "cu-str-0191", "section": "service", "who": "choir", "text": "Токи жизни проливающая Божия Премудрость, / во гроб заходящи, животворит / сущия в незаходимых адовых местех."},
  {"id": "cu-str-0192", "section": "service", "who": "choir", "text": "85 Поведаша мне законопреступницы глумления, / но не яко закон Твой, Господи."},
  {"id": "cu-str-0193", "section": "service", "who": "choir", "text": "Да человеческое обновлю сокрушенное естество, / уязвлен есмь смертию хотя плотию: / Мати Моя, не терзайся рыданьми."},
  {"id": "cu-str-0194", "section": "service", "who": "choir", "text": "86 Вся заповеди Твоя истина, / неправедно погнаша мя, помози ми."},
  {"id": "cu-str-0195", "section": "service", "who": "choir", "text": "Зашел еси под землю, Светоносец правды, / и мертвыя якоже от сна воздвигл еси, / отгнав всякую тьму сущую во аде."},
  {"id": "cu-str-0196", "section": "service", "who": "choir", "text": "87 Вмале не скончаша мене на земли: / аз же не оставих заповедей Твоих."},
  {"id": "cu-str-0197", "section": "service", "who": "choir", "text": "Зерно двоерасленное естественножизненное, / в бока земная сеется со слезами днесь: / но прозябше мир радостносотворит."},
  {"id": "cu-str-0198", "section": "service", "who": "choir", "text": "88 По милости Твоей живи мя, / и сохраню свидения уст Твоих."},
  {"id": "cu-str-0199", "section": "service", "who": "choir", "text": "Убояся Адам, Богу ходящу в раи: / радуется же, ко аду сошедшу, / падый прежде, и ныне воздвизаемь."},
  {"id": "cu-str-0200", "section": "service", "who": "choir", "text": "89 Во век Господи, слово Твое / пребывает на небеси."},
  {"id": "cu-str-0201", "section": "service", "who": "choir", "text": "Жрет Тебе жертвы слезныя рождшая Тя Христе, / плотию положена во гробе, вопиющи: / востани Чадо, якоже предрекл еси."},
  {"id": "cu-str-0202", "section": "service", "who": "choir", "text": "90 В род и род истина Твоя, / основал еси землю, и пребывает."},
  {"id": "cu-str-0203", "section": "service", "who": "choir", "text": "Во гробе Иосиф благоговейно Тя новем сокрывая / песни исходныя боголепныя поет Тебе, / смешеныя рыданьми Спасе."},
  {"id": "cu-str-0204", "section": "service", "who": "choir", "text": "91 Учинением Твоим пребывает день, / яко всяческая работна Тебе."},
  {"id": "cu-str-0205", "section": "service", "who": "choir", "text": "Гвоздьми Тя Кресту пригвождена, / Мати Твоя Слове зрящи, / гвоздьми печали горькия пронзает, и стрелами душу."},
  {"id": "cu-str-0206", "section": "service", "who": "choir", "text": "92 Яко аще бы не закон Твой поучение мое был, / тогда убо погибл бых во смирении моем."},
  {"id": "cu-str-0207", "section": "service", "who": "choir", "text": "Тя всех наслаждение Мати зрящи, / питием напаяема горьким, / слезами лице омакает горце."},
  {"id": "cu-str-0208", "section": "service", "who": "choir", "text": "93 Во век не забуду оправданий Твоих, / яко в них оживил мя еси."},
  {"id": "cu-str-0209", "section": "service", "who": "choir", "text": "Уязвляюся люте, и растерзаюся утробою Слове, зрящи неправедное Твое заколение, глаголаше Пречистая с плачем."},
  {"id": "cu-str-0210", "section": "service", "who": "choir", "text": "94 Твой есмь аз, спаси мя, / яко оправданий Твоих взысках."},
  {"id": "cu-str-0211", "section": "service", "who": "choir", "text": "Око сладкое, и устне Твои како заключу Слове? / Како же Тя мертволепно погребу? / Ужасаюся, вопияше Иосиф."},
  {"id": "cu-str-0212", "section": "service", "who": "choir", "text": "95 Мене ждаша грешницы погубити мя, / свидения Твоя разумех."},
  {"id": "cu-str-0213", "section": "service", "who": "choir", "text": "Песни Иосиф и Никодим надгробныя / поют Христу умершему ныне, / поют же с ними и Серафими."},
  {"id": "cu-str-0214", "section": "service", "who": "choir", "text": "96 Всякия кончины видех конец, / широка заповедь Твоя зело."},
  {"id": "cu-str-0215", "section": "service", "who": "choir", "text": "Заходиши под землю Спасе, Солнце правды: / темже Рождшая Тя Луна печальми оскудевает, / вида Твоего лишаема."},
  {"id": "cu-str-0216", "section": "service", "who": "choir", "text": "97 Коль возлюбих закон Твой Господи, / весь день поучение мое есть."},
  {"id": "cu-str-0217", "section": "service", "who": "choir", "text": "Ужасеся ад Спасе, зря Тя Жизнодавца, / богатство онаго упраждняюща, / и яже от века мертвыя возставляюща."},
  {"id": "cu-str-0218", "section": "service", "who": "choir", "text": "98 Паче враг моих умудрил мя еси заповедию Твоею, / яко в век моя есть."},
  {"id": "cu-str-0219", "section": "service", "who": "choir", "text": "Солнце свет возсиявает по нощи Слове: / и Ты же воскрес, просияваеши по смерти ясно, / яко от чертога."},
  {"id": "cu-str-0220", "section": "service", "who": "choir", "text": "99 Паче всех учащих мя разумех, / яко свидения Твоя поучение мое есть."},
  {"id": "cu-str-0221", "section": "service", "who": "choir", "text": "Земля Тя Создателю, в недра приемши, / трепетом содержима Спасе трясется, / успивши мертвыя трясением."},
  {"id": "cu-str-0222", "section": "service", "who": "choir", "text": "100 Паче старец разумех, / яко заповеди Твоя взысках."},
  {"id": "cu-str-0223", "section": "service", "who": "choir", "text": "Миры Тя Христе, Никодим и Благообразный, / ныне новолепно помазующе, / ужаснися, вопияху, вся земля."},
  {"id": "cu-str-0224", "section": "service", "who": "choir", "text": "101 От всякаго пути лукава возбраних ногам моим, / яко да сохраню словеса Твоя."},
  {"id": "cu-str-0225", "section": "service", "who": "choir", "text": "Зашел еси Светотворче, / и с Тобою зайде свет солнца: / трепетом же тварь содержится, / всех Тя проповедающи Творца."},
  {"id": "cu-str-0226", "section": "service", "who": "choir", "text": "102 От судеб Твоих не уклонихся, / яко Ты законоположил ми еси."},
  {"id": "cu-str-0227", "section": "service", "who": "choir", "text": "Камень углажденный, краеугольный покрывает камень: / человек же смертный яко смертна, / Бога покрывает ныне во гробе: / ужаснися земле."},
  {"id": "cu-str-0228", "section": "service", "who": "choir", "text": "103 Коль сладка гортани моему словеса Твоя, / паче меда устом моим."},
  {"id": "cu-str-0229", "section": "service", "who": "choir", "text": "Виждь ученика, егоже любил еси, / и Твою Матерь Чадо, / и вещание даждь сладчайшее, / взываше плачущи Чистая."},
  {"id": "cu-str-0230", "section": "service", "who": "choir", "text": "104 От заповедей Твоих разумех, / сего ради возненавидех всяк путь неправды."},
  {"id": "cu-str-0231", "section": "service", "who": "choir", "text": "Ты Слове, яко сый живота Датель, / иудеов, на Кресте прострыйся, не умертвил еси, / но воскресил еси и сих мертвыя."},
  {"id": "cu-str-0232", "section": "service", "who": "choir", "text": "105 Светильник ногама моима закон Твой, / и свет стезям моим."},
  {"id": "cu-str-0233", "section": "service", "who": "choir", "text": "Доброты Слове прежде не имел еси, / ниже вида, егда страдал еси, / но воскрес провозсиял еси, / удобрив человеки Божественными зарями."},
  {"id": "cu-str-0234", "section": "service", "who": "choir", "text": "106 Кляхся, и поставих / сохранити судьбы правды Твоея."},
  {"id": "cu-str-0235", "section": "service", "who": "choir", "text": "Зашел еси плотию в землю, Невечерний Светоносец, / и не терпя зрети солнце померче, / полудни еще сущу."},
  {"id": "cu-str-0236", "section": "service", "who": "choir", "text": "107 Смирихся до зела Господи, / живи мя по словеси Твоему."},
  {"id": "cu-str-0237", "section": "service", "who": "choir", "text": "Солнце вкупе и луна померкше Спасе, / рабом благоразумным образовахуся, / иже в черныя одежды облачатся."},
  {"id": "cu-str-0238", "section": "service", "who": "choir", "text": "108 Вольная уст моих благоволи же / Господи, и судьбам Твоим научи мя."},
  {"id": "cu-str-0239", "section": "service", "who": "choir", "text": "Виде Тя Бога сотник, аще и умертвился еси: / како Тя убо Боже мой, осяжу рукама? / Ужасаюся, вопияше Иосиф."},
  {"id": "cu-str-0240", "section": "service", "who": "choir", "text": "109 Душа моя в руку Твоею выну, / и закона Твоего не забых."},
  {"id": "cu-str-0241", "section": "service", "who": "choir", "text": "Усну Адам, но смерть из ребр изводит: / Ты же ныне уснул еси Слове Божий, / источаеши от ребр Твоих мирови жизнь."},
  {"id": "cu-str-0242", "section": "service", "who": "choir", "text": "110 Положиша грешницы сеть мне, / и от заповедей Твоих не заблудих."},
  {"id": "cu-str-0243", "section": "service", "who": "choir", "text": "Уснул еси мало, и оживил еси умершия, / и воскрес, воскресил еси спящия от века Блаже."},
  {"id": "cu-str-0244", "section": "service", "who": "choir", "text": "111 Наследовах свидения Твоя во век, / яко радование сердца моего суть."},
  {"id": "cu-str-0245", "section": "service", "who": "choir", "text": "Взят еси от земли, / но источил еси спасения вино, животочная Лозо: / прославляю Страсть и Крест."},
  {"id": "cu-str-0246", "section": "service", "who": "choir", "text": "112 Приклоних сердце мое, / сотворити оправдания Твоя в век за воздаяние."},
  {"id": "cu-str-0247", "section": "service", "who": "choir", "text": "Како умная чиноначалия Тя Спасе поют, / нага, окровавлена, осуждена, / терпяще дерзость распинателей?"},
  {"id": "cu-str-0248", "section": "service", "who": "choir", "text": "113 Законопреступныя возненавидех, / закон же Твой возлюбих."},
  {"id": "cu-str-0249", "section": "service", "who": "choir", "text": "Обрученный, стропотнейший роде еврейский, / ведал еси воздвижение храма, / почто осудил еси Христа?"},
  {"id": "cu-str-0250", "section": "service", "who": "choir", "text": "114 Помощник мой, и Заступник мой еси Ты, / на словеса Твоя уповах."},
  {"id": "cu-str-0251", "section": "service", "who": "choir", "text": "Во одежду поругания Украсителя всех облекаеши, / Иже небо утверди, и землю украси чудно."},
  {"id": "cu-str-0252", "section": "service", "who": "choir", "text": "115 Уклонитеся от мене, лукавнующии, / и испытаю заповеди Бога моего."},
  {"id": "cu-str-0253", "section": "service", "who": "choir", "text": "Якоже неясыть уязвлен в ребра Твоя Слове, / отроки Твоя умершия оживил еси, / искапав животныя им токи."},
  {"id": "cu-str-0254", "section": "service", "who": "choir", "text": "116 Заступи мя по словеси Твоему и жив буду, / и не посрами мене от чаяния моего."},
  {"id": "cu-str-0255", "section": "service", "who": "choir", "text": "Солнце прежде устави Иисус, иноплеменники секий: / Ты же скрылся еси, низлагая тьмы начальника."},
  {"id": "cu-str-0256", "section": "service", "who": "choir", "text": "117 Помози ми, и спасуся, / и поучуся во оправданиих Твоих выну."},
  {"id": "cu-str-0257", "section": "service", "who": "choir", "text": "Недр Отеческих неисходен пребыв Щедре, / и Человек быти благоволил еси, / и во ад снизшел еси Христе."},
  {"id": "cu-str-0258", "section": "service", "who": "choir", "text": "118 Уничижил еси вся отступающия от оправданий Твоих, / яко неправедно помышление их."},
  {"id": "cu-str-0259", "section": "service", "who": "choir", "text": "Взятся распныйся, / иже на водах землю повешей, / и яко бездыханен в ней ныне возлегает: / яже не терпящи трясашеся люте."},
  {"id": "cu-str-0260", "section": "service", "who": "choir", "text": "119 Преступающия непщевах вся грешныя земли: / сего ради возлюбих свидения Твоя."},
  {"id": "cu-str-0261", "section": "service", "who": "choir", "text": "Увы мне, о Сыне, / Неискусомужная рыдаше глаголющи: / Егоже бо яко Царя надеяхся, / осуждена зрю ныне на Кресте."},
  {"id": "cu-str-0262", "section": "service", "who": "choir", "text": "120 Пригвозди страху Твоему плоти моя, / от судеб бо Твоих убояхся."},
  {"id": "cu-str-0263", "section": "service", "who": "choir", "text": "Сия Гавриил Мне возвести, егда слете, / иже Царство вечное рече, Сына Моего Иисуса."},
  {"id": "cu-str-0264", "section": "service", "who": "choir", "text": "121 Сотворих суд и правду, / не предаждь мене обидящим мя."},
  {"id": "cu-str-0265", "section": "service", "who": "choir", "text": "Увы, Симеоново совершися пророчество: / Твой бо меч пройде сердце Мое, Еммануиле."},
  {"id": "cu-str-0266", "section": "service", "who": "choir", "text": "122 Восприими раба Твоего во благо, / да не оклеветают мене гордии."},
  {"id": "cu-str-0267", "section": "service", "who": "choir", "text": "Поне сущих от мертвых постыдитеся, о иудее! / Ихже Животодавец возстави, / Егоже вы убисте завистно."},
  {"id": "cu-str-0268", "section": "service", "who": "choir", "text": "123 Очи мои исчезосте во спасение Твое, / и в слово правды Твоея."},
  {"id": "cu-str-0269", "section": "service", "who": "choir", "text": "Ужасеся видевшее, невидимый Свете, / Тебе Христе мой во гробе сокрываема, бездыханна же, / и помрачи солнце свет."},
  {"id": "cu-str-0270", "section": "service", "who": "choir", "text": "124 Сотвори с рабом Твоим по милости Твоей / и оправданием Твоим научи мя."},
  {"id": "cu-str-0271", "section": "service", "who": "choir", "text": "Плакаше горько Пренепорочная Мати Твоя Слове, / егда во гробе виде Тебе Неизреченнаго и Безначальнаго Бога."},
  {"id": "cu-str-0272", "section": "service", "who": "choir", "text": "125 Раб Твой есмь аз, вразуми мя, / и увем свидения Твоя."},
  {"id": "cu-str-0273", "section": "service", "who": "choir", "text": "Мертвость Твою нетленная Христе, / Мати Твоя зрящи, / горько к Тебе вещаше: / не косни Животе в мертвых."},
  {"id": "cu-str-0274", "section": "service", "who": "choir", "text": "126 Время сотворити Господеви, / разориша закон Твой."},
  {"id": "cu-str-0275", "section": "service", "who": "choir", "text": "Ад лютый потрепета, / егда Тя виде Солнце Славы Безсмертне, / и издаваше юзники тщательно."},
  {"id": "cu-str-0276", "section": "service", "who": "choir", "text": "127 Сего ради возлюбих заповеди Твоя / паче злата и топазия."},
  {"id": "cu-str-0277", "section": "service", "who": "choir", "text": "Велие и ужасное видение ныне зрится: / живота сый Виновный, смерть подъят, / оживити хотя всех."},
  {"id": "cu-str-0278", "section": "service", "who": "choir", "text": "128 Сего ради ко всем заповедем Твоим направляхся, / всяк путь неправды возненавидех."},
  {"id": "cu-str-0279", "section": "service", "who": "choir", "text": "Прободаешися в ребра, / и пригвождаешися Владыко руками, / язву от ребра Ты исцеляя, / и невоздержание рук праотец."},
  {"id": "cu-str-0280", "section": "service", "who": "choir", "text": "129 Дивна свидения Твоя, / сего ради испыта я душа моя."},
  {"id": "cu-str-0281", "section": "service", "who": "choir", "text": "Прежде Рахилина сына плакаше всяк иже в дому, / и Сына Девыя рыдаху ученик лик с Материю."},
  {"id": "cu-str-0282", "section": "service", "who": "choir", "text": "130 Явление словес Твоих / просвещает, и вразумляет младенцы."},
  {"id": "cu-str-0283", "section": "service", "who": "choir", "text": "Ударение рук даша Христовой ланите, / рукою человека создавшаго, / и челюсти зверя сокрушившаго."},
  {"id": "cu-str-0284", "section": "service", "who": "choir", "text": "131 Уста моя отверзох, и привлекох Дух, / яко заповедей Твоих желах."},
  {"id": "cu-str-0285", "section": "service", "who": "choir", "text": "Песньми Твое Христе, ныне распятие и погребение, вси вернии празднуем, / избавльшеся смерти погребением Твоим."},
  {"id": "cu-str-0286", "section": "service", "who": "choir", "text": "Слава, Троичен: Безначальне Боже, Соприсносущне Слове, и Душе Святый! / Люди православныя в вере укрепи на ратныя, яко Благ."},
  {"id": "cu-str-0287", "section": "service", "who": "choir", "text": "И ныне, Богородичен: Жизнь рождшая, / Пренепорочная Чистая Дево, / утоли церковныя соблазны, / и подаждь мир, яко Благая."},
  {"id": "cu-str-0288", "section": "service", "who": "rubric", "text": "И паки первый тропарь оба лика:"},
  {"id": "cu-str-0289", "section": "service", "who": "choir", "text": "Достойно есть / величати Тя Жизнодавца, / на Кресте руце простершаго, / и сокрушшаго державу вражию."},
  {"id": "cu-str-0290", "section": "service", "who": "rubric", "text": "Таже ектения малая. Возглас во вторую статию:"},
  {"id": "cu-str-0291", "section": "service", "who": "choir", "text": "Яко Свят еси Боже наш, Иже на престоле славы Херувимстем почиваяй, и Тебе славу возсылаем, со Безначальным Твоим Отцем, и с Пресвятым, и Благим, и Животворящим Твоим Духом, ныне и присно, и во веки веков."},
  {"id": "cu-str-0292", "section": "service", "who": "rubric", "text": "И начинаем третию статию, кадящу священнику."},
  {"id": "cu-str-0293", "section": "service", "who": "choir", "text": "Статия третия."},
  {"id": "cu-str-0294", "section": "service", "who": "rubric", "text": "Начинает паки со сладкопением десный, сиречь первый лик, на глас 3-й:"},
  {"id": "cu-str-0295", "section": "service", "who": "choir", "text": "Роди вси песнь / погребению Твоему приносят, Христе мой."},
  {"id": "cu-str-0296", "section": "service", "who": "choir", "text": "132 Призри на мя, и помилуй мя, / по суду любящих имя Твое."},
  {"id": "cu-str-0297", "section": "service", "who": "choir", "text": "Снем с древа иже от Аримафеа, / плащаницею обвив / во гробе Тя погребает."},
  {"id": "cu-str-0298", "section": "service", "who": "choir", "text": "133 Стопы моя направи по словеси Твоему, / и да не обладает мною всякое беззаконие."},
  {"id": "cu-str-0299", "section": "service", "who": "choir", "text": "Мироносицы приидоша, / мира Тебе Христе мой, носящия премудро."},
  {"id": "cu-str-0300", "section": "service", "who": "choir", "text": "134 Избави мя от клеветы человеческия, / и сохраню заповеди Твоя."},
  {"id": "cu-str-0301", "section": "service", "who": "choir", "text": "Гряди вся тварь, / песни исходныя принесем Зиждителю."},
  {"id": "cu-str-0302", "section": "service", "who": "choir", "text": "135 Лице Твое просвети на раба Твоего, / и научи мя оправданием Твоим."},
  {"id": "cu-str-0303", "section": "service", "who": "choir", "text": "Яко мертва Живаго / с мироносицами, вси миропомажем мудренно."},
  {"id": "cu-str-0304", "section": "service", "who": "choir", "text": "136 Исходища водная изведосте очи мои, / понеже не сохраних закона Твоего."},
  {"id": "cu-str-0305", "section": "service", "who": "choir", "text": "Иосифе треблаженне, / погреби тело Христа Жизнодавца."},
  {"id": "cu-str-0306", "section": "service", "who": "choir", "text": "137 Праведен еси Господи, / и прави суди Твои."},
  {"id": "cu-str-0307", "section": "service", "who": "choir", "text": "Ихже воспита манною, / воздвигоша пяту на Благодетеля."},
  {"id": "cu-str-0308", "section": "service", "who": "choir", "text": "138 Заповедал еси правду, свидения Твоя, / и истину зело."},
  {"id": "cu-str-0309", "section": "service", "who": "choir", "text": "Ихже воспита манною, / приносят Спасу желчь купно и оцет."},
  {"id": "cu-str-0310", "section": "service", "who": "choir", "text": "139 Истаяла мя есть ревность Твоя, / яко забыша словеса Твоя врази мои."},
  {"id": "cu-str-0311", "section": "service", "who": "choir", "text": "О пребезумия и христоубийства пророкоубийц!"},
  {"id": "cu-str-0312", "section": "service", "who": "choir", "text": "140 Разжжено слово Твое зело, / и раб Твой возлюби е."},
  {"id": "cu-str-0313", "section": "service", "who": "choir", "text": "Якоже безумный служитель, / предаде ученик бездну премудрости."},
  {"id": "cu-str-0314", "section": "service", "who": "choir", "text": "141 Юнейший аз есмь и уничижен, / оправданий Твоих не забых."},
  {"id": "cu-str-0315", "section": "service", "who": "choir", "text": "Избавителя оставив, / пленник оставися льстивый Иуда."},
  {"id": "cu-str-0316", "section": "service", "who": "choir", "text": "142 Правда Твоя правда во век, / и закон Твой истина."},
  {"id": "cu-str-0317", "section": "service", "who": "choir", "text": "По Соломону, ров глубокий, / уста еврей беззаконных."},
  {"id": "cu-str-0318", "section": "service", "who": "choir", "text": "143 Скорби и нужди обретоша мя, / заповеди Твоя поучение мое."},
  {"id": "cu-str-0319", "section": "service", "who": "choir", "text": "В стропотных шествиих евреов беззаконных, волчцы и сети."},
  {"id": "cu-str-0320", "section": "service", "who": "choir", "text": "144 Правда свидения Твоя в век: / вразуми мя, и жив буду."},
  {"id": "cu-str-0321", "section": "service", "who": "choir", "text": "Иосиф погребает с Никодимом мертволепно Зиждителя."},
  {"id": "cu-str-0322", "section": "service", "who": "choir", "text": "145 Воззвах всем сердцем моим, услыши мя Господи, / оправдания Твоя взыщу."},
  {"id": "cu-str-0323", "section": "service", "who": "choir", "text": "Жизнодавче Спасе, / слава державе Твоей, ад разоршей."},
  {"id": "cu-str-0324", "section": "service", "who": "choir", "text": "146 Воззвах Ти, спаси мя, / и сохраню свидения Твоя."},
  {"id": "cu-str-0325", "section": "service", "who": "choir", "text": "Лежаща Тя Пречистая видящи, Слове, / матеролепно плакаше."},
  {"id": "cu-str-0326", "section": "service", "who": "choir", "text": "147 Предварих в безгодии, и воззвах, / на словеса Твоя уповах."},
  {"id": "cu-str-0327", "section": "service", "who": "choir", "text": "О сладчайшая Моя весно, сладчайшее Мое Чадо! / Где Твоя зайде доброта?"},
  {"id": "cu-str-0328", "section": "service", "who": "choir", "text": "148 Предваристе очи мои ко утру, / поучитися словесем Твоим."},
  {"id": "cu-str-0329", "section": "service", "who": "choir", "text": "Плачь сподвизаше Всечистая Твоя Мати, / Тебе Слове умершу."},
  {"id": "cu-str-0330", "section": "service", "who": "choir", "text": "149 Глас мой услыши Господи, по милости Твоей, / по судьбе Твоей живи мя."},
  {"id": "cu-str-0331", "section": "service", "who": "choir", "text": "Жены с миры приидоша / помазати Христа Божественнаго мира."},
  {"id": "cu-str-0332", "section": "service", "who": "choir", "text": "150 Приближишася гонящии мя беззаконием, / от закона же Твоего удалишася."},
  {"id": "cu-str-0333", "section": "service", "who": "choir", "text": "Смерть смертию Ты умерщвляеши Боже мой, / Божественною силою Твоею."},
  {"id": "cu-str-0334", "section": "service", "who": "choir", "text": "151 Близ еси Ты Господи, / и вси путие Твои истина."},
  {"id": "cu-str-0335", "section": "service", "who": "choir", "text": "Прельстися прелестник, / прельстивыйся избавляется, / премудростию Твоею Боже мой."},
  {"id": "cu-str-0336", "section": "service", "who": "choir", "text": "152 Исперва познах от свидений Твоих, / яко во век основал я еси."},
  {"id": "cu-str-0337", "section": "service", "who": "choir", "text": "Во дно адово низведен бысть предатель, / в кладенец истления."},
  {"id": "cu-str-0338", "section": "service", "who": "choir", "text": "153 Виждь смирение мое, и изми мя, / яко закона Твоего не забых."},
  {"id": "cu-str-0339", "section": "service", "who": "choir", "text": "Волчцы и сети путие / треокаяннаго безумнаго Иуды."},
  {"id": "cu-str-0340", "section": "service", "who": "choir", "text": "154 Суди суд мой, и избави мя, / словесе ради Твоего живи мя."},
  {"id": "cu-str-0341", "section": "service", "who": "choir", "text": "Вси спогибают распинателие Твои Слове, / Сыне Божий Всецарю."},
  {"id": "cu-str-0342", "section": "service", "who": "choir", "text": "155 Далече от грешник спасение, / яко оправданий Твоих не взыскаша."},
  {"id": "cu-str-0343", "section": "service", "who": "choir", "text": "В кладенец истления вси спогибают мужие кровей."},
  {"id": "cu-str-0344", "section": "service", "who": "choir", "text": "156 Щедроты Твоя многи Господи, / по судьбе Твоей живи мя."},
  {"id": "cu-str-0345", "section": "service", "who": "choir", "text": "Сыне Божий Всецарю Боже мой, Создателю мой, / како страсть подъял еси?"},
  {"id": "cu-str-0346", "section": "service", "who": "choir", "text": "157 Мнози изгонящии мя и стужающии ми, / от свидений Твоих не уклонихся."},
  {"id": "cu-str-0347", "section": "service", "who": "choir", "text": "Юница Тельца на древе повешена взываше зрящи."},
  {"id": "cu-str-0348", "section": "service", "who": "choir", "text": "158 Видех неразумевающия и истаях, / яко словес Твоих не сохраниша."},
  {"id": "cu-str-0349", "section": "service", "who": "choir", "text": "Тело живоносное Иосиф погребает с Никодимом."},
  {"id": "cu-str-0350", "section": "service", "who": "choir", "text": "159 Виждь, яко заповеди Твоя возлюбих Господи, / по милости Твоей живи мя."},
  {"id": "cu-str-0351", "section": "service", "who": "choir", "text": "Взываше Отроковица / тепле слезы точащи, / утробою прободаема."},
  {"id": "cu-str-0352", "section": "service", "who": "choir", "text": "160 Начало словес Твоих истина, / и во век вся судьбы правды Твоея."},
  {"id": "cu-str-0353", "section": "service", "who": "choir", "text": "Свете очию Моею, / Сладчайшее Мое Чадо! / Како во гробе ныне покрываешися?"},
  {"id": "cu-str-0354", "section": "service", "who": "choir", "text": "161 Князи погнаша мя туне, / и от словес Твоих убояся сердце мое."},
  {"id": "cu-str-0355", "section": "service", "who": "choir", "text": "Адама и Еву свободити, Мати не рыдай, сия стражду."},
  {"id": "cu-str-0356", "section": "service", "who": "choir", "text": "162 Возрадуюся аз о словесех Твоих, / яко обретаяй корысть многу."},
  {"id": "cu-str-0357", "section": "service", "who": "choir", "text": "Прославляю Твое, Сыне Мой, крайнее благоутробие, / егоже ради сия страждеши."},
  {"id": "cu-str-0358", "section": "service", "who": "choir", "text": "163 Неправду возненавидех и омерзих, / закон же Твой возлюбих."},
  {"id": "cu-str-0359", "section": "service", "who": "choir", "text": "Оцтом напоен был еси и желчию Щедре, / древнее разрешая вкушение."},
  {"id": "cu-str-0360", "section": "service", "who": "choir", "text": "164 Седмерицею днем хвалих Тя, / о судьбах правды Твоея."},
  {"id": "cu-str-0361", "section": "service", "who": "choir", "text": "На кресте пригвоздился еси, / древле люди Твоя столпом облачным покрываяй."},
  {"id": "cu-str-0362", "section": "service", "who": "choir", "text": "165 Мир мног любящим закон Твой, / и несть им соблазна."},
  {"id": "cu-str-0363", "section": "service", "who": "choir", "text": "Мироносицы Спасе ко гробу пришедшия, / мира принесоша Тебе."},
  {"id": "cu-str-0364", "section": "service", "who": "choir", "text": "166 Чаях спасения Твоего Господи, / и заповеди Твоя возлюбих."},
  {"id": "cu-str-0365", "section": "service", "who": "choir", "text": "Востани Щедре, / от пропастей адских возставляяй нас."},
  {"id": "cu-str-0366", "section": "service", "who": "choir", "text": "167 Сохрани душа моя свидения Твоя, / и возлюби я зело."},
  {"id": "cu-str-0367", "section": "service", "who": "choir", "text": "Воскресни Жизнодавче, / рождшая Тя Мати слезы точащи глаголет."},
  {"id": "cu-str-0368", "section": "service", "who": "choir", "text": "168 Сохраних заповеди Твоя и свидения Твоя, / яко вси путие мои пред Тобою, Господи."},
  {"id": "cu-str-0369", "section": "service", "who": "choir", "text": "Потщися воскреснути, печаль разрешая Слове, / чисто Рождшия Тя."},
  {"id": "cu-str-0370", "section": "service", "who": "choir", "text": "169 Да приближится моление мое пред Тя Господи, / по словеси Твоему вразуми мя."},
  {"id": "cu-str-0371", "section": "service", "who": "choir", "text": "Небесныя силы ужасошася страхом, / мертва Тя зряще."},
  {"id": "cu-str-0372", "section": "service", "who": "choir", "text": "170 Да внидет прошение мое пред Тя Господи, / по словеси Твоему избави мя."},
  {"id": "cu-str-0373", "section": "service", "who": "choir", "text": "Любовию же и страхом Страсти Твоя почитающим, / даждь прегрешений разрешение."},
  {"id": "cu-str-0374", "section": "service", "who": "choir", "text": "171 Отрыгнут устне мои пение, / егда научиши мя оправданием Твоим."},
  {"id": "cu-str-0375", "section": "service", "who": "choir", "text": "О ужаснаго и страннаго видения, Божий Слове! / Како земля Тя спокрывает?"},
  {"id": "cu-str-0376", "section": "service", "who": "choir", "text": "172 Провещает язык мой словеса Твоя, / яко вся заповеди Твоя правда."},
  {"id": "cu-str-0377", "section": "service", "who": "choir", "text": "Носяй Тя древле Спасе, Иосиф бегает, / и ныне Тя иный погребает."},
  {"id": "cu-str-0378", "section": "service", "who": "choir", "text": "173 Да будет рука Твоя еже спасти мя, / яко заповеди Твоя изволих."},
  {"id": "cu-str-0379", "section": "service", "who": "choir", "text": "Плачет и рыдает Тя Пречистая Мати Твоя, Спасе мой умерщвленаго."},
  {"id": "cu-str-0380", "section": "service", "who": "choir", "text": "174 Возжелах спасение Твое Господи, / и закон Твой поучение мое есть."},
  {"id": "cu-str-0381", "section": "service", "who": "choir", "text": "Ужасаются умы страннаго, / и ужаснаго Тебе всех Создателя, погребения."},
  {"id": "cu-str-0382", "section": "service", "who": "choir", "text": "175 Жива будет душа моя, и восхвалит Тя, / и судьбы Твоя помогут мне."},
  {"id": "cu-str-0383", "section": "service", "who": "choir", "text": "Излияша на гроб мироносицы мира, / зело рано пришедшыя."},
  {"id": "cu-str-0384", "section": "service", "who": "choir", "text": "176. Заблудих яко овча погибшее, / взыщи раба Твоего, яко заповедей Твоих не забых."},
  {"id": "cu-str-0385", "section": "service", "who": "choir", "text": "Мир Церкви, / людем Твоим спасение / даруй востанием Твоим."},
  {"id": "cu-str-0386", "section": "service", "who": "choir", "text": "Слава: О Троице Боже мой, / Отче, Сыне и Душе, / помилуй мир."},
  {"id": "cu-str-0387", "section": "service", "who": "choir", "text": "И ныне: Видети Твоего Сына Воскресение, / Дево, сподоби Твоя рабы."},
  {"id": "cu-str-0388", "section": "service", "who": "choir", "text": "И абие поем тропари сия, во глас 5:"},
  {"id": "cu-str-0389", "section": "service", "who": "choir", "text": "Благословен еси, Господи, / научи мя оправданием Твоим."},
  {"id": "cu-str-0390", "section": "service", "who": "choir", "text": "Ангельский собор удивися, / зря Тебе в мертвых вменившася, / смертную же Спасе крепость разоривша, / и с Собою Адама воздвигша, / и от ада вся свобождша."},
  {"id": "cu-str-0391", "section": "service", "who": "choir", "text": "Благословен еси, Господи, / научи мя оправданием Твоим."},
  {"id": "cu-str-0392", "section": "service", "who": "choir", "text": "Почто мира с милостивными слезами, / о ученицы растворяете? / Блистаяйся во гробе Ангел мироносицам вещаше: / видите вы гроб и уразумейте, / Спас бо воскресе от гроба."},
  {"id": "cu-str-0393", "section": "service", "who": "choir", "text": "Благословен еси, Господи, / научи мя оправданием Твоим."},
  {"id": "cu-str-0394", "section": "service", "who": "choir", "text": "Зело рано мироносицы течаху / ко гробу Твоему рыдающия, / но предста к ним Ангел и рече: / рыдания время преста, не плачите: / Воскресение же апостолом рцыте."},
  {"id": "cu-str-0395", "section": "service", "who": "choir", "text": "Благословен еси, Господи, / научи мя оправданием Твоим."},
  {"id": "cu-str-0396", "section": "service", "who": "choir", "text": "Мироносицы жены, с миры пришедшия / ко гробу Твоему Спасе, рыдаху, / Ангел же к ним рече, глаголя: / что с мертвыми Живаго помышляете? / Яко Бог бо воскресе от гроба."},
  {"id": "cu-str-0397", "section": "service", "who": "choir", "text": "Слава, Троичен: Поклонимся Отцу, / и Его Сынови, и Святому Духу, / Святей Троице во Едином Существе, / с Серафимы зовуще: / Свят, Свят, Свят еси Господи."},
  {"id": "cu-str-0398", "section": "service", "who": "choir", "text": "И ныне, Богородичен: Жизнодавца рождши, / греха Дево Адама избавила еси, / радость же Еве / в печали место подала еси: / падшия же от жизни / к сей направи, / из Тебе воплотивыйся Бог и Человек."},
  {"id": "cu-str-0399", "section": "service", "who": "choir", "text": "Аллилуиа, трижды."},
  {"id": "cu-str-0400", "section": "service", "who": "rubric", "text": "Таже ектения малая."},
  {"id": "cu-str-0401", "section": "service", "who": "rubric", "text": "Возглас:"},
  {"id": "cu-str-0402", "section": "service", "who": "choir", "text": "Ты бо еси Царь мира, Христе Боже наш, и Тебе славу возсылаем, со Безначальным Твоим Отцем, и с Пресвятым, и Благим, и Животворящим Твоим Духом, ныне и присно, и во веки веков."},
  {"id": "cu-str-0403", "section": "service", "who": "choir", "text": "И поем седален дне, глас 1. Подобен: Гроб Твой, Спасе:"},
  {"id": "cu-str-0404", "section": "service", "who": "choir", "text": "Плащаницею чистою, и ароматы Божественными / Тело Честное, испросив у Пилата миропомазует, / и полагает Иосиф в новом гробе. / Темже уранше мироносицы жены, возопиша: / покажи нам, якоже предрекл еси Христе, Воскресение."},
  {"id": "cu-str-0405", "section": "service", "who": "choir", "text": "Слава: Покажи нам, якоже предрекл еси Христе, Воскресение."},
  {"id": "cu-str-0406", "section": "service", "who": "choir", "text": "И ныне, другий подобен: Ужасошася лицы Ангельстии, / зряще Седящаго в недрех Отчих: / како во гроб полагается, яко мертв Безсмертный! / Егоже чини Ангельстии окружают / и славят с мертвыми во аде, / яко Зиждителя и Господа."},
  {"id": "cu-str-0407", "section": "service", "who": "rubric", "text": "Таже бывает чтение во Евангелии толковом, от Матфеа, зачало 114:"},
  {"id": "cu-str-0408", "section": "service", "who": "reader", "text": "Во утрий же день, иже есть по пятце: Воскресение Христово:"},
  {"id": "cu-str-0409", "section": "service", "who": "rubric", "text": "не глаголем. Но абие псалом 50."},
  {"id": "cu-str-0410", "section": "service", "who": "rubric", "text": "И поем канон, ирмос по дважды, а тропари на 12. И паки последи ирмос оба лика вкупе. Есть же канон, от первыя песни до шестыя, творение Марка монаха, епископа Идруитскаго: ирмосы же творение жены некия, Кассии именуемыя. От 6-я же песни до конца творение господина Космы. Краегранесие же канона:"},
  {"id": "cu-str-0411", "section": "service", "who": "priest", "text": "Каи симерон де Савватон мелпо Мега. Сиесть:"},
  {"id": "cu-str-0412", "section": "service", "who": "priest", "text": "И днесь же Субботу пою Великую. Глас 6."},
  {"id": "cu-str-0413", "section": "service", "who": "choir", "text": "Песнь 1. Ирмос:"},
  {"id": "cu-str-0414", "section": "service", "who": "choir", "text": "Волною морскою / Скрывшаго древле, / гонителя мучителя, под землею скрыша / спасенных отроцы; / но мы, яко отроковицы, / Господеви поим, / славно бо прославися."},
  {"id": "cu-str-0415", "section": "service", "who": "choir", "text": "{Κ} Господи Боже мой, / исходное пение, и надгробную Тебе песнь воспою, / погребением Твоим жизни моея входы отверзшему, / и смертию смерть и ад умертвившему."},
  {"id": "cu-str-0416", "section": "service", "who": "choir", "text": "{Α} Горе Тя на Престоле и доле во гробе, / премирная и подземная, помышляющая Спасе мой, / зыбляхуся умерщвлением Твоим: / паче ума бо виден был еси мертв, Живоначальниче."},
  {"id": "cu-str-0417", "section": "service", "who": "choir", "text": "{Ι} Да Твоея славы вся исполниши, / сшел еси в нижняя земли: / от Тебе бо не скрыся состав мой, иже во Адаме, и погребен, / истлевша мя обновляеши, Человеколюбче."},
  {"id": "cu-str-0418", "section": "service", "who": "choir", "text": "Песнь 3. Ирмос:"},
  {"id": "cu-str-0419", "section": "service", "who": "choir", "text": "Тебе, на водах / повесившаго / всю землю неодержимо, / тварь видевши / на лобнем висима, / ужасом многим содрогашеся, / несть свят, / разве Тебе Господи, взывающи."},
  {"id": "cu-str-0420", "section": "service", "who": "choir", "text": "{Σ} Образы погребения Твоего показал еси, видения умножив. / Ныне же сокровенная Твоя богомужно уяснил еси, и сущим во аде Владыко, / несть свят, разве Тебе Господи, взывающим."},
  {"id": "cu-str-0421", "section": "service", "who": "choir", "text": "{Η} Простерл еси длани, и соединил еси древле разстоящаяся. / Одеянием же Спасе, еже в плащанице и во гробе, / окованныя разрешил еси, / несть свят, разве Тебе Господи, взывающия."},
  {"id": "cu-str-0422", "section": "service", "who": "choir", "text": "{Μ} Гробом и печатьми, Невместиме, / содержимь был еси хотением: / ибо силу Твою действы показал еси, / богодейственно поющим: / несть свят, разве Тебе Господи, Человеколюбче."},
  {"id": "cu-str-0423", "section": "service", "who": "choir", "text": "Седален, глас 1: Гроб Твой Спасе, воини стрегущии, / мертви от облистания явльшагося Ангела быша, / проповедающа женам Воскресение. / Тебе славим, тли потребителя! / Тебе припадаем, Воскресшему из гроба, / и Единому Богу нашему!"},
  {"id": "cu-str-0424", "section": "service", "who": "choir", "text": "Слава, и ныне, тойже."},
  {"id": "cu-str-0425", "section": "service", "who": "choir", "text": "Песнь 4. Ирмос:"},
  {"id": "cu-str-0426", "section": "service", "who": "choir", "text": "На Кресте Твое / Божественное истощание / провидя Аввакум, / ужасся, вопияше: / Ты сильных пресекл еси / державу Блаже, / приобщаяся сущим во аде, яко Всесилен."},
  {"id": "cu-str-0427", "section": "service", "who": "choir", "text": "{Ε} Седьмый день днесь освятил еси, / егоже древле благословил еси упокоением дел: / преводиши бо всяческая и обновляеши, / субботствуя Спасе мой, и назидая."},
  {"id": "cu-str-0428", "section": "service", "who": "choir", "text": "{Ρ} Силою лучшаго, победившаго Тебе, / от плоти душа Твоя разделися, / растерзающи бо обоя узы, / смерти и ада, Слове, державою Твоею."},
  {"id": "cu-str-0429", "section": "service", "who": "choir", "text": "{Ο} Ад Слове, срет Тя огорчися, / человека зря обожена, / уязвлена ранами, и Всесильнодетеля, / страшным же зраком погибе."},
  {"id": "cu-str-0430", "section": "service", "who": "choir", "text": "Песнь 5. Ирмос:"},
  {"id": "cu-str-0431", "section": "service", "who": "choir", "text": "Богоявления Твоего Христе, / к нам милостивно бывшаго, / Исаия Свет видев Невечерний, / из нощи утреневав взываше: / воскреснут мертвии, / и востанут сущии во гробех, / и вси земнороднии возрадуются."},
  {"id": "cu-str-0432", "section": "service", "who": "choir", "text": "{Ν} Новотвориши земныя Создателю, перстен быв, / и плащаница и гроб являют еже в Тебе Слове, таинство. / Благообразный бо советник, Тебе Рождшаго совет образует, / в Тебе велелепно новотворящаго мя."},
  {"id": "cu-str-0433", "section": "service", "who": "choir", "text": "{Δ} Смертию смертное, / погребением тленное прелагаеши, / нетленно твориши бо, / боголепно безсмертно творя приятие, / плоть бо Твоя истления не виде Владыко, / ниже душа Твоя во аде страннолепно оставлена бысть."},
  {"id": "cu-str-0434", "section": "service", "who": "choir", "text": "{Ε} Из Небрачныя прошед, и прободен в ребра Содетелю мой, / из Нея соделал еси обновление Евино, Адам быв, / уснув паче естества сном естественным, / и жизнь воздвигнув от сна и тления, яко Всесилен."},
  {"id": "cu-str-0435", "section": "service", "who": "choir", "text": "Песнь 6. {Σ} Ирмос:"},
  {"id": "cu-str-0436", "section": "service", "who": "choir", "text": "Ят бысть, / но не удержан в персех китовых Иона: / Твой бо образ нося, / Страдавшаго, и погребению давшагося, / яко от чертога от зверя изыде. / Приглашаше же кустодии, / хранящии суетная и ложная, / милость сию оставили есте."},
  {"id": "cu-str-0437", "section": "service", "who": "choir", "text": "{Α} Биен был еси, но не разделился еси Слове, / еяже причастился еси плоти: / аще бо и разорися Твой храм во время страсти, / но и тако един бе состав Божества и плоти Твоея. / Во обоих бо Един еси Сын, Слово Божие, Бог и Человек."},
  {"id": "cu-str-0438", "section": "service", "who": "choir", "text": "{Β} Человекоубийственно, но не богоубийственно бысть прегрешение Адамово: / аще бо и пострада Твоея плоти перстное существо, / но Божество безстрастно пребысть, / тленное же Твое на нетление преложил еси, / и нетленныя жизни показал еси источник Воскресением."},
  {"id": "cu-str-0439", "section": "service", "who": "choir", "text": "{Β} Царствует ад, но не вечнует над родом человеческим: / Ты бо положся во гробе Державне, живоначальною дланию, / смерти ключи развергл еси, / и проповедал еси от века тамо спящим, избавление неложное / быв Спасе, мертвым первенец."},
  {"id": "cu-str-0440", "section": "service", "who": "choir", "text": "Кондак, глас 6: Бездну заключивый, мертв зрится, / и смирною и плащаницею обвився, / во гробе полагается яко смертный Безсмертный: / жены же приидоша помазати Его миром, / плачущия горько и вопиющия: / сия суббота есть преблагословенная, / в нейже Христос уснув, воскреснет тридневен. Икос:"},
  {"id": "cu-str-0441", "section": "service", "who": "choir", "text": "Содержай вся на Крест вознесеся, / и рыдает вся тварь, Того видящи нага висяща на древе, / солнце лучи сокры, и звезды отложиша свет: / земля же со многим страхом поколебася, и море побеже, / и камение распадеся, гроби же многи отверзошася, / и телеса восташа святых мужей. / Ад низу стенет, / и иудее советуют оклеветати Христово Воскресение. / Жены же взывают: / сия суббота есть преблагословенная, / в нейже Христос, уснув, воскреснет тридневен. Синаксарий."},
  {"id": "cu-str-0442", "section": "service", "who": "choir", "text": "Песнь 7. {Α} Ирмос:"},
  {"id": "cu-str-0443", "section": "service", "who": "choir", "text": "Неизреченное чудо, / в пещи избавивый / преподобныя отроки из пламене, / во гробе мертв / бездыханен полагается, / во спасение нас поющих: / Избавителю Боже, / благословен еси."},
  {"id": "cu-str-0444", "section": "service", "who": "choir", "text": "{Τ} Уязвися ад, в сердце / прием Уязвеннаго копием в ребра, / и воздыхает огнем Божественным иждиваемь, / во спасение нас поющих: / Избавителю Боже, благословен еси."},
  {"id": "cu-str-0445", "section": "service", "who": "choir", "text": "{Ο} Богат гроб, / в себе бо приим яко спяща Содетеля, / жизни Божественное сокровище показася, / во спасение нас поющих: / Избавителю Боже, благословен еси."},
  {"id": "cu-str-0446", "section": "service", "who": "choir", "text": "{Ν} Законом умерших / еже во гробе положение, всех приемлет Жизнь, / и сего источника показует востания, / во спасение нас поющих: / Избавителю Боже, благословен еси."},
  {"id": "cu-str-0447", "section": "service", "who": "choir", "text": "{Μ} Едино бяше неразлучное, / еже во аде, и во гробе, и во Едеме, / Божество Христово, со Отцем и Духом, / во спасение нас поющих: / Избавителю Боже, благословен еси."},
  {"id": "cu-str-0448", "section": "service", "who": "choir", "text": "Песнь 8. {Ε} Ирмос:"},
  {"id": "cu-str-0449", "section": "service", "who": "choir", "text": "Ужаснися бояйся небо, / и да подвижатся основания земли: / се бо в мертвецех вменяется в вышних Живый, / и во гроб мал странноприемлется. / Егоже отроцы благословите, / священницы воспойте, / людие превозносите во вся веки."},
  {"id": "cu-str-0450", "section": "service", "who": "choir", "text": "{Λ} Разрушися Пречистый храм, / падшую же совозставляет скинию: / Адаму бо первому Вторый, Иже в вышних Живый, / сниде даже до адовых сокровищ. / Егоже отроцы благословите, / священницы воспойте, / людие превозносите во вся веки."},
  {"id": "cu-str-0451", "section": "service", "who": "choir", "text": "{Π} Преста дерзость учеников, / Аримафей же изрядствует Иосиф: / мертва бо и нага зря, над всеми Бога, / просит и погребает, зовый: / отроцы благословите, / священницы воспойте, / людие, превозносите во вся веки."},
  {"id": "cu-str-0452", "section": "service", "who": "choir", "text": "{Ω} О чудес новых! / О благости! / О неизреченнаго терпения! / Волею бо под землею печатлеется, Иже в вышних Живый, / и яко льстец, Бог оклеветается. / Егоже отроцы благословите, / священницы воспойте, / людие превозносите во вся веки."},
  {"id": "cu-str-0453", "section": "service", "who": "choir", "text": "Песнь 9. {Μ} Ирмос:"},
  {"id": "cu-str-0454", "section": "service", "who": "choir", "text": "Не рыдай Мене Мати, / зрящи во гробе, / Егоже во чреве без семене зачала еси Сына: / востану бо и прославлюся, / и вознесу со славою, непрестанно яко Бог, / верою и любовию Тя величающия."},
  {"id": "cu-str-0455", "section": "service", "who": "choir", "text": "{Ε} В страннем Твоем рождестве, / болезней избежавше паче естества, / ублажихся Безначальне Сыне: / ныне же Тя Боже мой, / бездыханна зрящи мертва, / оружием печали растерзаюся люте, / но воскресни, яко да возвеличуся."},
  {"id": "cu-str-0456", "section": "service", "who": "choir", "text": "{Γ} Земля покрывает Мя хотяща, / но устрашаются адовы вратницы, / одеяна видяще одеждею окровавленою, Мати, отмщения: / враги бо Крестом поразив яко Бог, / воскресну паки, и возвеличу Тя."},
  {"id": "cu-str-0457", "section": "service", "who": "choir", "text": "{Α} Да радуется тварь, / да веселятся вси земнороднии, / враг бо пленися ад: / с миры жены да сретают, / Адама со Евою избавляю всеродна, / и в третий день воскресну."},
  {"id": "cu-str-0458", "section": "service", "who": "choir", "text": "Ексапостиларий, глас 2:"},
  {"id": "cu-str-0459", "section": "service", "who": "choir", "text": "Свят Господь Бог наш. (3) Стих:"},
  {"id": "cu-str-0460", "section": "service", "who": "choir", "text": "Яко свят Господь Бог наш. Стих:"},
  {"id": "cu-str-0461", "section": "service", "who": "choir", "text": "Над всеми людьми Бог наш."},
  {"id": "cu-str-0462", "section": "service", "who": "choir", "text": "На хвалитех поставим стихи 4 и поем стихиры самогласны, глас 2:"},
  {"id": "cu-str-0463", "section": "service", "who": "choir", "text": "Днесь содержит гроб Содержащаго дланию тварь, / покрывает камень Покрывшаго добродетелию небеса: / спит Живот, и ад трепещет, / и Адам от уз разрешается. / Слава Твоему смотрению, / имже совершив все упокоение вечное, / даровал еси нам Боже, / всесвятое из мертвых Твое Воскресение."},
  {"id": "cu-str-0464", "section": "service", "who": "choir", "text": "Что зримое видение? / Кое настоящее упокоение? / Царь веков, Иже страстию совершив смотрение, / во гробе субботствует, новое нам подая субботство. / Тому возопиим: / воскресни Боже, судяй земли, / яко Ты царствуеши во веки, / неизмерную имеяй велию милость."},
  {"id": "cu-str-0465", "section": "service", "who": "choir", "text": "Приидите видим Живот наш во гробе лежащь, / да во гробех лежащия оживит. / Приидите днесь Иже из Иуды спяща зряще, / пророчески Ему возопиим: / возлег уснул еси яко лев, / кто воздвигнет Тя Царю? / Но востани самовластно, / давый Себе о нас волею, / Господи слава Тебе. Глас 6:"},
  {"id": "cu-str-0466", "section": "service", "who": "choir", "text": "Проси Иосиф тело Иисусово, / и положи е в новем своем гробе: / подобаше бо Ему из гроба, / яко из чертога проити. / Сокрушивый державу смерти, / и отверзый врата райская человеком, / Господи, слава Тебе."},
  {"id": "cu-str-0467", "section": "service", "who": "choir", "text": "Слава, глас 6: Днешний день тайно великий Моисей / прообразоваше, глаголя: / и благослови Бог день седьмый, / сия бо есть благословенная суббота. / Сей есть упокоения день, / воньже почи от всех дел Своих Единородный Сын Божий, / смотрением еже на смерть, плотию субботствовав: / и во еже бе, паки возвращься Воскресением, / дарова нам живот вечный, / яко Един Благ и Человеколюбец."},
  {"id": "cu-str-0468", "section": "service", "who": "choir", "text": "И ныне, Богородичен, глас 2: Преблагословена еси, Богородице Дево, / Воплощшим бо ся из Тебе ад пленися, / Адам воззвася, клятва потребися, Ева свободися, / смерть умертвися, и мы ожихом. / Тем воспевающе вопием: / благословен Христос Бог, благоволивый тако, слава Тебе."},
  {"id": "cu-str-0469", "section": "service", "who": "rubric", "text": "Славословие великое. Священник же облачается во всю священническую одежду, и входит со святым Евангелием. По Трисвятом же глаголет Священник:"},
  {"id": "cu-str-0470", "section": "service", "who": "priest", "text": "Вонмем. Мир всем. Премудрость."},
  {"id": "cu-str-0471", "section": "service", "who": "choir", "text": "И мы тропарь, глас 2, единожды:"},
  {"id": "cu-str-0472", "section": "service", "who": "choir", "text": "Благообразный Иосиф, / с древа снем Пречистое Тело Твое, / плащаницею чистою обвив, / и вонями во гробе нове покрыв положи."},
  {"id": "cu-str-0473", "section": "service", "who": "choir", "text": "И глаголем тропарь пророчества, глас 2:"},
  {"id": "cu-str-0474", "section": "service", "who": "choir", "text": "Содержай концы, / гробом содержатися изволил еси, Христе, / да от адова поглощения избавиши человечество / и воскрес оживиши нас, / яко Бог Безсмертный."},
  {"id": "cu-str-0475", "section": "service", "who": "choir", "text": "Слава, И воскрес оживиши нас, яко Бог Безсмертный."},
  {"id": "cu-str-0476", "section": "service", "who": "choir", "text": "И ныне, весь."},
  {"id": "cu-str-0477", "section": "service", "who": "choir", "text": "Таже прокимен, глас 4:"},
  {"id": "cu-str-0478", "section": "service", "who": "choir", "text": "Воскресни Господи, помози нам, / и избави нас имене ради Твоего. Стих:"},
  {"id": "cu-str-0479", "section": "service", "who": "choir", "text": "Боже, ушима нашима услышахом и отцы наши возвестиша нам."},
  {"id": "cu-str-0480", "section": "service", "who": "choir", "text": "Пророчества Иезекиилева чтение. [Глава 37, ст. 1 – 14.]"},
  {"id": "cu-str-0481", "section": "service", "who": "choir", "text": "Бысть на мне рука Господня, и изведе мя в дусе Господни, и постави мя среде поля, се же бяше полно костей человеческих. И обведе мя окрест их около, и се многи зело на лицы поля, и се сухи зело. И рече ко мне: сыне человечь, оживут ли кости сия? И рекох: Господи Боже, Ты веси сия. И рече ко мне: сыне человечь, прорцы на кости сия, и речеши им: кости сухия, слышите слово Господне. Се глаголет Адонаи Господь костем сим: ее Аз введу в вас дух животен. И дам на вас жилы, и возведу на вас плоть, и простру по вам кожу, и дам дух Мой в вас, и оживете, и увесте, яко Аз есмь Господь. И прорекох, якоже заповеда ми Господь. И бысть глас внегда ми пророчествовати, и се трус, и совокупляхуся кости, кость к кости, каяждо к составу своему. И видех, и се быша им жилы, и плоть растяше, и восхождаше, [и протяжеся] им кожа верху, духа же не бяше в них. И рече ко мне: прорцы о дусе, прорцы сыне человечь, и рцы духови: сия глаголет Адонаи Господь, от четырех ветров прииди душе, и вдуни на мертвыя сия, и да оживут. И прорекох, якоже повеле ми: и вниде в ня дух жизни, и ожиша, и сташа на ногах своих, собор мног зело. И рече Господь ко мне, глаголя: сыне человечь, сия кости весь дом Израилев есть, тии бо глаголют: сухи быша кости наша, погибе надежда наша, убиени быхом. Того ради прорцы [сыне человечь], и рцы к ним, сия глаголет Адонаи Господь: се Аз отверзу гробы ваша, и изведу вас от гроб ваших, людие Мои, и введу вы в землю Израилеву. И увесте, яко Аз есмь Господь, внегда отверсти Ми гробы ваша, еже возвести Ми вас от гробов ваших, людие Мои: и дам дух Мой в вас, и живи будете. И поставлю вы на земли вашей, и увесте, яко Аз Господь: глаголах, и сотворю, глаголет Адонаи Господь."},
  {"id": "cu-str-0482", "section": "service", "who": "choir", "text": "Прокимен, глас 7:"},
  {"id": "cu-str-0483", "section": "service", "who": "choir", "text": "Воскресни Господи Боже мой, да вознесется рука Твоя, / не забуди убогих Твоих до конца. Стих:"},
  {"id": "cu-str-0484", "section": "service", "who": "choir", "text": "Исповемся Тебе, Господи, всем сердцем моим, повем вся чудеса Твоя."},
  {"id": "cu-str-0485", "section": "service", "who": "choir", "text": "Апостол к Коринфянам, зачало 133: Братие, мал квас все смешение квасит. Очистите убо ветхий квас, да будете ново смешение, якоже есте безквасни: ибо Пасха наша за ны пожрен бысть, Христос. Темже да празднуем, не в квасе ветсе, ни в квасе злобы и лукавства, но в безквасиих чистоты и истины. Христос ны искупил есть от клятвы законныя, быв по нас клятва. Писано бо есть: проклят всяк висяй на древе. Да в языцех благословение Авраамле будет о Христе Иисусе, да обетование Духа приимем верою."},
  {"id": "cu-str-0486", "section": "service", "who": "choir", "text": "Аллилуиа, глас 5:"},
  {"id": "cu-str-0487", "section": "service", "who": "choir", "text": "Да воскреснет Бог, и расточатся врази Его, и да бежат от Лица Его ненавидящии Его. Стих:"},
  {"id": "cu-str-0488", "section": "service", "who": "choir", "text": "Яко исчезает дым, да исчезнут, яко тает воск от лица огня. Стих:"},
  {"id": "cu-str-0489", "section": "service", "who": "choir", "text": "Тако да погибнут грешницы от Лица Божия, а праведницы да возвеселятся."},
  {"id": "cu-str-0490", "section": "service", "who": "choir", "text": "Евангелие от Матфеа, зачало 114:"},
  {"id": "cu-str-0491", "section": "service", "who": "choir", "text": "Во утрий день, иже есть по пятце, собрашася архиерее и фарисее к Пилату, глаголюще: господи, помянухом, яко льстец он рече, еще сый жив: по триех днех востану. Повели убо утвердити гроб до третияго дне, да не како пришедше ученицы Его нощию, украдут Его, и рекут людем: воста от мертвых, и будет последняя лесть горша первыя. Рече же им Пилат: имате кустодию, идите, утвердите, якоже весте. Они же шедше утвердиша гроб, знаменавше камень с кустодиею. Таже ектения:"},
  {"id": "cu-str-0492", "section": "service", "who": "choir", "text": "Рцем вси:"},
  {"id": "cu-str-0493", "section": "service", "who": "rubric", "text": "и прочая, яко обычно."},
  {"id": "cu-str-0494", "section": "service", "who": "choir", "text": "Исполним утреннюю молитву нашу:"},
  {"id": "cu-str-0495", "section": "service", "who": "rubric", "text": "Такожде и прочая, яко обычно. И бывает отпуст. И бывает целование плащаницы, а идеже несть плащаницы, целуют образ;"},
  {"id": "cu-str-0496", "section": "service", "who": "choir", "text": "Певцы же поют стихиру, глас 5:"},
  {"id": "cu-str-0497", "section": "service", "who": "choir", "text": "Приидите, ублажим Иосифа приснопамятнаго, / в нощи к Пилату пришедшаго, / и Живота всех испросившаго. / Даждь ми Сего страннаго, / Иже не имеет где главы подклонити; / даждь ми Сего страннаго, Егоже ученик лукавый на смерть предаде; / даждь ми Сего страннаго, / Егоже Мати зрящи на Кресте висяща, / рыдающи вопияше, / и матерски восклицаше: / увы Мне, Чадо Мое! / Увы Мне, Свете Мой, / и утроба Моя возлюбленная! / Симеоном бо предреченное в церкви днесь собысться: / Мое сердце оружие пройде, / но в радость Воскресения Твоего / плач преложи. / Покланяемся Страстем Твоим, Христе; / покланяемся Страстем Твоим, Христе; / покланяемся Страстем Твоим, Христе, / и Святому Воскресению."},
  {"id": "cu-str-0498", "section": "service", "who": "rubric", "text": "Первый же час поется в притворе: третий же час, шестый и девятый поются вкупе просто в притворе с блаженными во свое время."},
  {"id": "cu-str-0499", "section": "service", "who": "choir", "text": "ВО СВЯТУЮ И ВЕЛИКУЮ СУББОТУ ВЕЧЕРА,"},
  {"id": "cu-str-0500", "section": "service", "who": "rubric", "text": "о часе десятом дне клеплет Вечерню. И облачается священник во одежду, и, благословившу ему, начинаем предначинательный псалом, посем ектения великая. Таже"},
  {"id": "cu-str-0501", "section": "service", "who": "choir", "text": "Господи, воззвах,"},
  {"id": "cu-str-0502", "section": "service", "who": "rubric", "text": "во глас 1. Обители же священницы и диакони вси, достигшу стиху, глаголющу:"},
  {"id": "cu-str-0503", "section": "service", "who": "deacon", "text": "Падут во мрежу свою:"},
  {"id": "cu-str-0504", "section": "service", "who": "rubric", "text": "полагающе поклон, отходят, и облачатся и сии во одежди, и творят проскомидию. И поставим стихов 8. Поем же стихиры воскресныя Осмогласника три, и от стиховны едину."},
  {"id": "cu-str-0505", "section": "service", "who": "choir", "text": "Воскресны, глас 1:"},
  {"id": "cu-str-0506", "section": "service", "who": "choir", "text": "Вечерняя наша молитвы / приими, Святый Господи, / и подаждь нам оставление грехов, / яко Един еси, / явлей в мире Воскресение."},
  {"id": "cu-str-0507", "section": "service", "who": "choir", "text": "Обыдите людие Сион, / и обымите его, / и дадите славу в нем Воскресшему из мертвых: / яко Той есть Бог наш, / избавлей нас от беззаконий наших."},
  {"id": "cu-str-0508", "section": "service", "who": "choir", "text": "Приидите людие / воспоим, и поклонимся Христу, / славяще Его из мертвых Воскресение: / яко Той есть Бог наш, / от лести вражия мир избавлей."},
  {"id": "cu-str-0509", "section": "service", "who": "choir", "text": "Страстию Твоею Христе, / от страстей свободихомся, / и Воскресением Твоим из истления избавихомся: / Господи, слава Тебе."},
  {"id": "cu-str-0510", "section": "service", "who": "choir", "text": "Ины стихиры самогласны, Великия Субботы три, повторяюще едину, глас 8:"},
  {"id": "cu-str-0511", "section": "service", "who": "choir", "text": "Днесь ад стеня вопиет: / уне мне бяше, аще бых от Марии Рождшагося не приял: / пришед бо на мя, державу мою разруши, / врата медная сокруши: / души, яже содержах прежде, Бог сый воскреси. / Слава Господи, Кресту Твоему, и Воскресению Твоему."},
  {"id": "cu-str-0512", "section": "service", "who": "choir", "text": "Днесь ад стеня вопиет: / разрушися моя власть, / приях Мертваго яко единаго от умерших, / Сего бо держати отнюд не могу, / но погубляю с Ним, имиже царствовах: / аз имех мертвецы от века, / но Сей [се] всех воздвизает. / Слава Господи Кресту Твоему, и Воскресению Твоему."},
  {"id": "cu-str-0513", "section": "service", "who": "choir", "text": "Днесь ад стеня вопиет: / пожерта моя бысть держава, / Пастырь распятся, и Адама воскреси: / имиже царствовах, лишихся, / и яже пожрох возмогий, всех изблевах. / Истощи гробы Распныйся, / изнемогает смертная держава. / Слава Господи Кресту Твоему, и Воскресению Твоему."},
  {"id": "cu-str-0514", "section": "service", "who": "choir", "text": "Слава, глас 6: Днешний день тайно великий Моисей прообразоваше, глаголя: / и благослови Бог день седьмый. / Сия бо есть благословенная Суббота, / сей есть упокоения день, / воньже почи от всех дел Своих, Единородный Сын Божий, / смотрением еже на смерть, плотию субботствовав: / и во еже бе, паки возвращься воскресением, / дарова нам живот вечный, / яко Един Благ, и Человеколюбец."},
  {"id": "cu-str-0515", "section": "service", "who": "choir", "text": "И ныне, Богородичен, глас 1: Всемирную славу / от человек прозябшую, / и Владыку рождшую, / небесную дверь / воспоим Марию Деву, / безплотных песнь, и верных удобрение; / Сия бо явися небо, и храм Божества; / Сия преграждение вражды разрушивши, / мир введе, и Царствие отверзе. / Сию убо имуще веры утверждение, / поборника имамы из Нея рождшагося Господа. / Дерзайте убо, дерзайте людие Божии: / ибо Той победит враги яко Всесилен."},
  {"id": "cu-str-0516", "section": "service", "who": "rubric", "text": "Вход с Евангелием."},
  {"id": "cu-str-0517", "section": "service", "who": "choir", "text": "Свете тихий:"},
  {"id": "cu-str-0518", "section": "service", "who": "rubric", "text": "Прокимен не глаголем, но абие:"},
  {"id": "cu-str-0519", "section": "service", "who": "choir", "text": "Премудрость."},
  {"id": "cu-str-0520", "section": "service", "who": "rubric", "text": "И начинает чтец чтения."},
  {"id": "cu-str-0521", "section": "service", "who": "choir", "text": "Бытия чтение: [Гл. 1, ст. 1 – 13]"},
  {"id": "cu-str-0522", "section": "service", "who": "choir", "text": "В начале сотвори Бог небо и землю. Земля же бе невидима, и неустроена, и тьма верху бездны, и Дух Божий ношашеся верху воды. И рече Бог: да будет свет. И бысть свет. И виде Бог свет, яко добро, и разлучи Бог между светом, и между тьмою. И нарече Бог свет день, а тьму нарече нощь. И бысть вечер, и бысть утро, день един."},
  {"id": "cu-str-0523", "section": "service", "who": "choir", "text": "И рече Бог: да будет твердь посреде воды, и да будет разлучающи посреде воды и воды. И бысть тако. И сотвори Бог твердь, и разлучи Бог между водою, яже бе под твердию, и между водою, яже бе над твердию. И нарече Бог твердь небо. И виде Бог, яко добро. И бысть вечер, и бысть утро, день вторый."},
  {"id": "cu-str-0524", "section": "service", "who": "choir", "text": "И рече Бог: да соберется вода, яже под небесем, в собрание едино, и да явится суша. И бысть тако. И собрася вода, яже под небесем, в собрания своя, и явися суша. И нарече Бог сушу, землю, и собрания вод нарече моря. И виде Бог, яко добро."},
  {"id": "cu-str-0525", "section": "service", "who": "choir", "text": "И рече Бог: да прорастит земля былие травное, сеющее семя по роду и по подобию, и древо плодовитое творящее плод, емуже семя его в нем по роду на земли. И бысть тако. И изнесе земля былие травное, сеющее семя по роду и по подобию, и древо плодовитое творящее плод, емуже семя его в нем по роду на земли. И виде Бог, яко добро. И бысть вечер, и бысть утро, день третий."},
  {"id": "cu-str-0526", "section": "service", "who": "choir", "text": "Пророчества Исаиина чтение: [Гл. 60, ст. 1 – 16]"},
  {"id": "cu-str-0527", "section": "service", "who": "choir", "text": "Светися светися Иерусалиме, прииде бо твой свет, и слава Господня на тебе возсия. Се тьма покрыет землю, и мрак на языки, на тебе же явится Господь, и слава Его на тебе узрится. И пойдут царие светом твоим, и языцы светлостию твоею. Возведи окрест очи твои, и виждь собраная чада твоя: се приидоша вси сынове твои издалеча, и дщери твои на рамех возмутся. Тогда узриши, и возрадуешися, и убоишися, и ужаснешися сердцем, яко преложится к тебе богатство морское, и языков и людей. И приидут к тебе стада вельблюд, и покрыют тя вельблюди Мадиамстии и Гефарстии: вси от Савы приидут, носяще злато, и ливан принесут, и камень честен, и спасение Господне благовозвестят. И вся овцы Кидарския соберутся тебе, и овни Навеофстии приидут к тебе, и вознесутся приятная на жертвенник Мой, и дом молитвы Моея прославится. Кии суть, иже яко облацы, летят, и яко голуби со птенцы ко Мне? Мене острови ждаша, и корабли Фарсийстии в первых, привести чада твоя издалеча, и сребро и злато их с ними, имене ради Господня Святаго, и за еже Святому Израилеву славну быти. И созиждут сынове инороднии стены твоя, и царие их предстояти будут тебе: за гнев бо Мой поразих тя, и за милость Мою возлюбих тя. И отверзутся врата твоя присно, день и нощь не затворятся, ввести к тебе силу язык, и цари их ведомыя. Языцы бо и царие, иже не поработают ти, погибнут, и языцы запустением запустеют. И слава Ливанова к тебе приидет, кипарисом, и певгом, и кедром, вкупе прославити место святое Мое, и место ног Моих прославлю. И пойдут к тебе боящеся сынове смиривших тя, и раздраживших тя, и поклонятся следам ног твоих вси прогневавшии тя: и наречешися град Господень, Сион Святаго Израилева. За сие, яко был еси оставлен и возненавиден, и не бе помогающаго ти, положу тя в радость вечную, веселие родом родов. И иссеши млеко языков, и богатство царей снеси, и уразумееши, яко Аз Господь спасаяй тя, и избавляяй тя Бог Израилев."},
  {"id": "cu-str-0528", "section": "service", "who": "choir", "text": "Исхода чтение: [Гл. 12, ст. 1 – 11]"},
  {"id": "cu-str-0529", "section": "service", "who": "choir", "text": "Рече Господь к Моисею и Аарону в земли Египетстей, глаголя: месяц сей вам начало месяцей, первый будет вам в месяцех лета. Рцы ко всему сонму сынов Израилевых, глаголя: в десятый месяца сего да возмет кийждо овча по домом отечеств, кийждо овча по дому. Аще же мало их есть в дому, яко не довольным быти на овча, да возмет с собою соседа ближняго своего по числу душ, кийждо довольное себе сочтет на овча. Овча совершенно, мужеск пол, непорочно и единолетно будет вам, от агнец и от козлищ приимете. И будет вам соблюдено даже до четвертагонадесять дне месяца сего: и заколют то все множество собора сынов Израилевых к вечеру. И приимут от крове, и помажут на обою подвою, и на прагах в домех, в нихже снедят тое. И снедят мяса в нощи той печена огнем и опресноки с горьким зелием снедят. Не снесте от них сурово, ниже варено в воде, но печеное огнем главу с ногами и со утробою. Не оставите от него до утрия, и кости не сокрушите от него: останки же от него до утра, огнем сожжете. Сице же снести е: чресла ваша препоясана, и сапози ваши на ногах ваших, и жезлы ваши в руках ваших: и снесте е со тщанием: пасха есть Господня."},
  {"id": "cu-str-0530", "section": "service", "who": "choir", "text": "Пророчества Ионина чтение: [Гл. 1, ст. 1 – 16. Гл. 2, ст. 1 – 3]"},
  {"id": "cu-str-0531", "section": "service", "who": "choir", "text": "Бысть слово Господне ко Ионе сыну Амафиину, глаголя: востани и иди в Ниневию град великий: и проповеждь в нем, яко взыде вопль злобы его ко Мне. И воста Иона, еже бежати в Фарсис от Лица Господня: и сниде во Иоппию, и обрете корабль идущь в Фарсис: и даде наем свой, и вниде вонь плыти с ними в Фарсис от Лица Господня. И Господь воздвиже ветр велий на мори, и бысть буря великая в мори, и корабль бедствоваше еже сокрушитися. И убояшася корабельницы, и возопиша кийждо к богу своему, и изметание сотвориша сосудов, иже в корабли, в море, еже облегчитися от них: Иона же сниде во дно корабля, и спаше ту, и храпляше. И прииде к нему кормчий, и рече ему: что ты храплеши? Востани, и моли Бога твоего, яко да спасет ны Бог, да не погибнем. И рече кийждо ко искреннему своему: приидите вержем жребия, и уразумеем, кого ради есть зло сие на нас. И метнуша жребия, и паде жребий на Иону. И реша к нему: возвести нам, кого ради сие зло на нас, и что твое делание есть, и откуду грядеши, и камо идеши, и от коея страны, и от киих людей еси ты? И рече к ним: раб Господень есмь аз, и Господа Бога Небеснаго аз чту, Иже сотвори море и сушу. И убояшася мужие страхом великим, и реша к нему: что сие сотворил еси? Зане разумеша мужие, яко от Лица Господня бежаше, яко возвести им. И реша к нему: что тебе сотворим, и утолится море от нас? Зане море восхождаше и воздвизаше паче волнение. И рече к ним Иона: возмите мя, и вверзите в море, и утолится море от вас: понеже познах аз, яко мене ради волнение сие великое на вы есть. И нуждахуся мужие возвратитися к земли, и не можаху, яко море восхождаше, и воздвизашеся паче на них. И возопиша к Господеви, и реша: никакоже Господи, да не погибнем души ради человека сего, и не даждь на нас крове праведныя: зане Ты Господи, якоже восхотел, сотворил еси. И взяша Иону, и ввергоша его в море, и преста море от волнения своего. И убояшася мужие страхом великим Господа, и пожроша жертву Господеви, и помолишася молитвами. И повеле Господь киту великому пожрети Иону: и бе Иона во чреве китове три дни и три нощи. И помолися Иона ко Господу Богу своему от чрева китова, и рече:"},
  {"id": "cu-str-0532", "section": "service", "who": "choir", "text": "Молитва: [Гл. 2, ст. 4 – 11. Гл. 3, ст. 1 – 10. Гл. 4, ст. 1 – 14]"},
  {"id": "cu-str-0533", "section": "service", "who": "choir", "text": "Возопих в скорби моей ко Господу Богу моему, и услыша мя: из чрева адова вопль мой, услышал еси глас мой. Отвергл мя еси в глубины сердца морскаго, и реки обыдоша мя: вся высоты Твоя, и волны Твоя на мне преидоша. И аз рех: отринулся от очию Твоею: еда приложу призрети ми к храму святому Твоему? Возлияся на мя вода до души моея, бездна обыде мя последняя, понре глава моя в разселины гор. Снидох в землю, еяже вереи ея заклепи вечнии: и да взыдет из истления живот мой к Тебе, Господи Боже мой. Внегда скончаватися от мене души моей, Господа помянух, и да приидет к Тебе молитва моя к храму святому Твоему. Хранящии суетная и ложная, милость свою оставиша. Аз же со гласом хваления и исповедания пожру Тебе, елика обещах, воздам Тебе во спасение мое Господеви. И повеле Господь китови, и изверже Иону на сушу."},
  {"id": "cu-str-0534", "section": "service", "who": "choir", "text": "И бысть слово Господне ко Ионе вторицею, глаголя: востани, и иди в Ниневию град великий, и проповеждь в нем по проповеди преждней, юже Аз глаголах тебе. И воста Иона, и иде в Ниневию, якоже глагола Господь: Ниневиа же бяше град велик Богу, яко шествия пути трех дней. И начат Иона входити во град, яко шествие пути дне единаго, и проповеда и рече: еще три дни, и Ниневиа превратится. И вероваша мужие Ниневийстии Богови, и заповедаша пост, и облекошася во вретища от велика их даже до мала их. И дойде слово к царю Ниневийскому, и воста с престола своего, и сверже ризы своя с себе, и облечеся во вретище, и седе на пепеле. И проповедася, и речено бысть в Ниневии от царя и вельмож его, глаголющих: человецы и скоти, и волове, и овцы да не вкусят ничесоже, ни да пасутся, ниже воды да пиют. И облекошася во вретища человецы, и скоти, и возопиша прилежно к Богу: и возвратися кийждо от пути своего лукаваго, и от неправды сущия в руках их, глаголюще: кто весть, аще раскается и умолен будет Бог, и обратится от гнева ярости Своея, и не погибнем? И виде Бог дела их, яко обратишася от путей своих лукавых: и раскаяся Бог о зле, еже глаголаше сотворити им, и не сотвори."},
  {"id": "cu-str-0535", "section": "service", "who": "choir", "text": "И опечалися Иона печалию великою, и смутися. И помолися ко Господу, и рече: о Господи, не сия ли убо словеса моя, яже глаголах, еще сущу ми на земли моей? Сего ради предварих бежати в Фарсис, зане разумех, яко милостив Ты еси и щедр, долготерпелив и многомилостив, и каяйся о злобах [человеческих]. И ныне Владыко Господи, приими душу мою от мене, яко уне ми умрети, нежели жити. И рече Господь ко Ионе: аще зело опечалился еси ты? И изыде Иона из града, и седе прямо града, и сотвори себе кущу, и седяше под нею в сени, дондеже увидит, что будет граду. И повеле Господь Бог тыкве, и возрасте над главою Иониною, да будет сень над главою его, еже осенити его от злых его: и возрадовася Иона о тыкве радостию великою. И повеле Господь Бог червию раннему во утрие, и подъяде тыкву, и изсше. И бысть вкупе внегда возсияти солнцу, и повеле Бог ветру знойну жегущу, и порази солнце на главу Ионину: и малодушствоваше, и отрицашеся души своея, и рече: уне ми умрети, нежели жити. И рече Господь Бог ко Ионе: зело ли опечалился еси ты о тыкве? И рече [Иона]: зело опечалихся аз даже до смерти. И рече Господь: ты оскорбился еси о тыкве, о нейже не трудился еси, ни воскормил еси ея, яже родися обнощь, и обнощь погибе. Аз же не пощажду ли Ниневии града великаго, в немже живут множайшии, неже дванадесять тем человек, иже не познаша десницы своея, ниже шуйцы своея, и скоти их мнози?"},
  {"id": "cu-str-0536", "section": "service", "who": "choir", "text": "Иисуса Навина чтение: [Гл. 5, ст. 1 – 15]"},
  {"id": "cu-str-0537", "section": "service", "who": "choir", "text": "Ополчишася сынове Израилевы в Галгалех, и сотвориша пасху в четвертыйнадесять день месяца от вечера на западе на поли Иерихонском. И ядоша от пшеницы земли оныя опресноки и новая. В той день преста манна, повнегда ядоша от пшеницы земли, и ктому не бысть сыном Израилевым манны, но ядоша от плодов земли Финическия в лето оное. И бысть егда бяше Иисус у Иерихона, и воззрев очима своима, виде человека стояща пред ним, и меч его обнажен в руце его. И приступив Иисус рече ему: наш ли еси, или от супостат наших? Он же рече ему: аз Архистратиг силы Господни, ныне приидох [семо]. И Иисус паде лицем своим на землю, и поклонися ему, и рече: господи, что повелеваеши рабу твоему? И рече Архистратиг Господень ко Иисусу: иззуй сапог с ногу твоею, место бо на немже ты стоиши свято есть. И сотвори Иисус тако."},
  {"id": "cu-str-0538", "section": "service", "who": "choir", "text": "Исхода чтение: [Гл. 13, ст. 20 – 22. Гл. 14, ст. 1 – 32. Гл. 15, ст. 1 – 19]"},
  {"id": "cu-str-0539", "section": "service", "who": "choir", "text": "Воздвигшеся сынове Израилевы от Сокхофа, ополчишася во Офоме при пустыни. Бог же вождаше их, в день убо столпом облачным, показати им путь, нощию же столпом огненным, светити им. И неоскуде столп облачный во дни, и столп огненный нощию, пред всеми людьми. И рече Господь к Моисею, глаголя: рцы сыном Израилевым, и обратившеся да ополчатся прямо придворию, между Магдолом и между морем, прямо Веельсенфону: пред ними ополчишися при мори. И речет фараон людем своим о сынех Израилевых: заблуждают сии по земли, затвори бо их пустыня. Аз же ожесточу сердце фараоново, и поженет созади их: и прославлюся в фараоне и во всем воинстве его, и уразумеют вси египтяне, яко Аз есмь Господь. И сотвориша тако."},
  {"id": "cu-str-0540", "section": "service", "who": "choir", "text": "И возвещено бысть царю египетскому, яко бежаша людие. И превратися сердце фараоново, и рабов его на люди, и рекоша: что сие сотворихом, отпустивше сыны Израилевы, да не работают нам? Впряже убо фараон колесницы своя, и вся люди своя собра с собою. И поят шесть сот колесниц избранных, и вся кони египетския, и тристаты над всеми. И ожесточи Господь сердце фараона царя египетскаго, и рабов его, и погна созади сынов Израилевых: сынове же Израилевы исхождаху рукою высокою. И погнаша египтяне в след их, и обретоша их ополчившихся при мори: и вси кони и колесницы фараоновы, и конницы, и воинство его прямо придворию, противу Веельсепфона."},
  {"id": "cu-str-0541", "section": "service", "who": "choir", "text": "И фараон приближашеся. Воззревше же сынове Израилевы очима, видеша: и се египтяне ополчишася в след их, и убояшася зело. И возопиша сынове Израилевы ко Господу, и рекоша к Моисею: за еже не быти гробом во Египте, извел еси нас умертвити в пустыни; что сие сотворил еси нам, извед нас из Египта? Не сей ли бяше глагол, егоже рекохом к тебе во Египте, глаголюще: остави нас, да работаем египтяном; лучше бо бяше нам работати египтяном, нежели умрети в пустыни сей. Рече же Моисей к людем: дерзайте, стойте, и зрите спасение еже от Господа, еже сотворит нам днесь. Имже бо образом видесте египтян днесь, не приложите ктому видети их в вечное время. Господь поборет по вас, вы же умолкните."},
  {"id": "cu-str-0542", "section": "service", "who": "choir", "text": "И рече Господь к Моисею: что вопиеши ко Мне? Рцы сыном Израилевым, и да путешествуют. Ты же возми жезл твой, и простри руку твою на море, и расторгни е: и да внидут сынове Израилевы посреде моря по суху. И се Аз ожесточу сердце фараоново, и всех египтян, и внидут в след их, и прославлюся в фараоне, и во всем воинстве его, и в колесницах, и в конех его. И уведят вси египтяне, яко Аз есмь Господь, егда прославлюся в фараоне, и в колесницах, и в конех его. Взятся же Ангел Божий ходяй пред полком сынов Израилевых, и пойде созади их: взятся же и столп облачный от лица их, и ста созади их. И вниде посреде полка египетска, и посреде полка сынов Израилевых, и ста: и бысть тьма и мрак, и прииде нощь, и не смесишася друг с другом во всю нощь. Простре же Моисей руку на море: и возгна Господь море ветром южным сильным всю нощь, и сотвори море сушу, и разступися вода. И внидоша сынове Израилевы посреде моря по суху: и вода им стена бысть одесную, и стена ошуюю. Погнаша же египтяне, и внидоша в след их, и всяк конь фараонов, и колесницы, и всадники посреде моря."},
  {"id": "cu-str-0543", "section": "service", "who": "choir", "text": "Бысть же в стражу утреннюю, и воззре Господь на полк египетский в столпе огненнем и облачном, и смяте полк египетский. И связа оси колесниц их, и ведяше их с нуждею. И рекоша египтяне: бежим от лица Израилева, Господь бо поборает по них на египтяны. И рече Господь к Моисею: простри руку твою на море, и да совокупится вода, и да покрыет египтяны, колесницы же и всадники. Простре же Моисей руку на море, и устроися вода ко дню на место: египтяне же бежаша под водою: и истрясе Господь египтяны посреде моря. И обратившися вода, покры колесницы и всадники, и всю силу фараонову, вшедши в след их в море, и не оста от них ни един. Сынове же Израилевы проидоша по суху посреде моря: вода же им стена [бысть] одесную и стена ошуюю. И избави Господь Израиля в день он из руки египетския: и видеша сынове Израилевы египтян измерших, при краи моря. Виде же Израиль руку великую, яже сотвори Господь египтяном: и убояшася людие Господа, и вероваша Богу, и Моисею угоднику Его. Тогда воспе Моисей, и сынове Израилевы песнь сию Господеви, и рекоша глаголюще:"},
  {"id": "cu-str-0544", "section": "service", "who": "rubric", "text": "Чтец глаголет:"},
  {"id": "cu-str-0545", "section": "service", "who": "reader", "text": "Поим Господеви:"},
  {"id": "cu-str-0546", "section": "service", "who": "rubric", "text": "И поют на глас 5:"},
  {"id": "cu-str-0547", "section": "service", "who": "reader", "text": "Славно бо прославися."},
  {"id": "cu-str-0548", "section": "service", "who": "rubric", "text": "И чтец коемуждо лику стихи предглаголет:"},
  {"id": "cu-str-0549", "section": "service", "who": "choir", "text": "Коня и всадника вверже в море. Поим Господеви:"},
  {"id": "cu-str-0550", "section": "service", "who": "rubric", "text": "И людие на оба лика поют:"},
  {"id": "cu-str-0551", "section": "service", "who": "choir", "text": "Славно бо прославися."},
  {"id": "cu-str-0552", "section": "service", "who": "choir", "text": "Помощник и Покровитель бысть мне во спасение. Поим Господеви:"},
  {"id": "cu-str-0553", "section": "service", "who": "choir", "text": "Славно бо прославися."},
  {"id": "cu-str-0554", "section": "service", "who": "choir", "text": "Сей мой Бог, и прославлю Его, Бог отца моего, и вознесу Его. Поим Господеви:"},
  {"id": "cu-str-0555", "section": "service", "who": "choir", "text": "Славно бо прославися."},
  {"id": "cu-str-0556", "section": "service", "who": "choir", "text": "Господь сокрушаяй брани, Господь имя Ему, колесницы фараоновы, и силу его вверже в море. Поим Господеви:"},
  {"id": "cu-str-0557", "section": "service", "who": "choir", "text": "Славно бо прославися."},
  {"id": "cu-str-0558", "section": "service", "who": "choir", "text": "Избранная всадники тристаты потопи в Чермнем мори. Поим Господеви:"},
  {"id": "cu-str-0559", "section": "service", "who": "choir", "text": "Славно бо прославися."},
  {"id": "cu-str-0560", "section": "service", "who": "choir", "text": "Пучиною покры их, погрязоша во глубине яко камень. Поим Господеви:"},
  {"id": "cu-str-0561", "section": "service", "who": "choir", "text": "Славно бо прославися."},
  {"id": "cu-str-0562", "section": "service", "who": "choir", "text": "Десница Твоя, Господи, прославися в крепости. Поим Господеви:"},
  {"id": "cu-str-0563", "section": "service", "who": "choir", "text": "Славно бо прославися."},
  {"id": "cu-str-0564", "section": "service", "who": "choir", "text": "Десная Твоя рука Господи, сокруши враги, и множеством славы Твоея стерл еси сопротивных. Поим Господеви:"},
  {"id": "cu-str-0565", "section": "service", "who": "choir", "text": "Славно бо прославися."},
  {"id": "cu-str-0566", "section": "service", "who": "choir", "text": "Послал еси гнев Твой, пояде я яко стеблие, и духом ярости Твоея разступися вода. Поим Господеви:"},
  {"id": "cu-str-0567", "section": "service", "who": "choir", "text": "Славно бо прославися."},
  {"id": "cu-str-0568", "section": "service", "who": "choir", "text": "Огустеша яко стена воды, огустеша и волны посреде моря. Поим Господеви:"},
  {"id": "cu-str-0569", "section": "service", "who": "choir", "text": "Славно бо прославися."},
  {"id": "cu-str-0570", "section": "service", "who": "choir", "text": "Рече враг: гнав постигну, разделю корысть, исполню душу мою, убию мечом моим, господствовати будет рука моя. Поим Господеви:"},
  {"id": "cu-str-0571", "section": "service", "who": "choir", "text": "Славно бо прославися."},
  {"id": "cu-str-0572", "section": "service", "who": "choir", "text": "Послал еси Духа Твоего, покры я море: погрязоша яко олово в воде зельней. Поим Господеви:"},
  {"id": "cu-str-0573", "section": "service", "who": "choir", "text": "Славно бо прославися."},
  {"id": "cu-str-0574", "section": "service", "who": "choir", "text": "Кто подобен Тебе в бозех, Господи? Кто подобен Тебе? Прославлен во святых, дивен в славе, творяй чудеса. Поим Господеви:"},
  {"id": "cu-str-0575", "section": "service", "who": "choir", "text": "Славно бо прославися."},
  {"id": "cu-str-0576", "section": "service", "who": "choir", "text": "Простерл еси десницу Твою, пожре я земля. Наставил еси правдою Твоею люди Твоя сия, яже избавил еси. Поим Господеви:"},
  {"id": "cu-str-0577", "section": "service", "who": "choir", "text": "Славно бо прославися."},
  {"id": "cu-str-0578", "section": "service", "who": "choir", "text": "Утешил еси крепостию Твоею во обитель святую Твою. Слышаша языцы, и прогневашася, болезни прияша живущии в Филистиме. Поим Господеви:"},
  {"id": "cu-str-0579", "section": "service", "who": "choir", "text": "Славно бо прославися."},
  {"id": "cu-str-0580", "section": "service", "who": "choir", "text": "Тогда потщашася владыки Едомстии, и князи Моавитстии, прият я трепет: растаяша вси живущии в Ханаане. Поим Господеви:"},
  {"id": "cu-str-0581", "section": "service", "who": "choir", "text": "Славно бо прославися."},
  {"id": "cu-str-0582", "section": "service", "who": "choir", "text": "Да нападет на ня страх и трепет, величием мышцы Твоея да окаменятся. Поим Господеви:"},
  {"id": "cu-str-0583", "section": "service", "who": "choir", "text": "Славно бо прославися."},
  {"id": "cu-str-0584", "section": "service", "who": "choir", "text": "Дондеже пройдут людие Твои Господи, дондеже пройдут людие Твои сии, яже стяжал еси. Поим Господеви:"},
  {"id": "cu-str-0585", "section": "service", "who": "choir", "text": "Славно бо прославися."},
  {"id": "cu-str-0586", "section": "service", "who": "choir", "text": "Введ насади я в гору достояния Твоего, в готовое жилище Твое, еже соделал еси Господи, святыню Господи, юже уготовасте руце Твои. Поим Господеви:"},
  {"id": "cu-str-0587", "section": "service", "who": "choir", "text": "Славно бо прославися."},
  {"id": "cu-str-0588", "section": "service", "who": "choir", "text": "Господь царствуяй веки, и на век, и еще. Егда вниде конница фараонова с колесницами и всадники в море, и наведе на них Господь воду морскую. Поим Господеви:"},
  {"id": "cu-str-0589", "section": "service", "who": "choir", "text": "Славно бо прославися."},
  {"id": "cu-str-0590", "section": "service", "who": "choir", "text": "Сынове же Израилевы проидоша сушею посреде моря. Поим Господеви:"},
  {"id": "cu-str-0591", "section": "service", "who": "choir", "text": "Славно бо прославися."},
  {"id": "cu-str-0592", "section": "service", "who": "choir", "text": "Слава Отцу, и Сыну, и Святому Духу. Поим Господеви:"},
  {"id": "cu-str-0593", "section": "service", "who": "choir", "text": "Славно бо прославися."},
  {"id": "cu-str-0594", "section": "service", "who": "choir", "text": "И ныне, и всегда, и во веки веков. Аминь. Поим Господеви:"},
  {"id": "cu-str-0595", "section": "service", "who": "choir", "text": "Славно бо прославися."},
  {"id": "cu-str-0596", "section": "service", "who": "rubric", "text": "И последи чтец поет тожде:"},
  {"id": "cu-str-0597", "section": "service", "who": "reader", "text": "Славно бо прославися."},
  {"id": "cu-str-0598", "section": "service", "who": "reader", "text": "Пророчества Софониева чтение: [Гл. 3, ст. 8 – 15]"},
  {"id": "cu-str-0599", "section": "service", "who": "reader", "text": "Тако глаголет Господь: потерпи Мене в день воскресения Моего во свидетельство: зане суд Мой в сонмища языков еже прияти царей, еже излияти на ня гнев Мой, весь гнев ярости Моея: зане огнем рвения Моего поядена будет вся земля. Яко тогда обращу к людем язык в род его, еже призывати всем имя Господне, работати ему под игом единем. От конец рек Ефиопских, прииму молящия Мя, в разсеянных Моих принесут жертвы Мне. В день он не имаши постыдитися от всех начинаний твоих, имиже нечествовал еси в Мя: яко тогда отыму от тебе укоризны досаждения твоего, и ктому не имаши приложити величатися на горе святей Моей. И оставлю в тебе люди кротки и смиренны, и будут благоговети о имени Господни. Останцы Израилевы, и не сотворят неправды, и не возглаголют суетных, и не обрящется во устех их язык льстив: зане тии пожируют, и угнездятся, и не будет устрашаяй их. Радуйся дщи Сионова зело, проповедуй дщи Иерусалимова, веселися и преукрашайся от всего сердца твоего, дщи Иерусалимля! Отъят Господь неправды твоя, избавил тя есть из руки враг твоих: воцарится Господь посреде тебе, и не узриши зла ктому."},
  {"id": "cu-str-0600", "section": "service", "who": "reader", "text": "Царств третиих чтение: [Гл. 17, ст. 8 – 23]"},
  {"id": "cu-str-0601", "section": "service", "who": "reader", "text": "Бысть глагол Господень ко Илии, глаголя: востани, и иди в Сарепту Сидонскую, и пребуди тамо: се бо заповедах тамо жене вдовице препитати тя. И воста, и иде в Сарепту Сидонскую, и прииде ко вратом града: и се тамо жена вдова собираше дрова. И возопи Илия вслед ея, и рече ей: принеси ныне ми мало воды в сосуде, и испию. И иде взяти. И возопи вслед ея Илия, и рече ей: приими убо мне и укрух хлеба в руце своей, да ям. И рече жена: жив Господь Бог твой, аще есть у мене опреснок, но токмо горсть муки в водоносе, и мало елеа в чванце: и се аз соберу два поленца, и вниду, и сотворю е себе и детем моим, и снемы е, и умрем. И рече к ней Илия: дерзай, вниди, и сотвори по глаголу твоему, но сотвори ми оттуду опреснок мал прежде, и принеси ми: себе же и чадом своим да сотвориши послежде. Яко тако глаголет Господь Бог Израилев: водонос муки не оскудеет, и чванец елеа не умалится до дне, дондеже даст Господь дождь на землю. И иде жена, и сотвори по глаголу Илиину, и даде ему, и яде той и та, и чада ея. И от того дне водонос муки не оскуде, и чванец елеа не умалися, по глаголу Господню, егоже глагола рукою Илииною."},
  {"id": "cu-str-0602", "section": "service", "who": "reader", "text": "И бысть по сих, и разболеся сын жены госпожи дому, и бе болезнь его крепка зело, дондеже не остася в нем дух его. И рече ко Илии: что мне, и тебе, человече Божий? Вшел еси ко мне воспомянути неправды моя, и уморити сына моего? И рече Илия к жене: даждь ми сына твоего. И взят его от недра ея, и вознесе его в горницу, идеже сам почиваше, и положи его на одре своем. И возопи Илия ко Господу, и рече: увы мне Господи, свидетелю вдовы, у неяже аз ныне пребываю, Ты озлобил еси еже уморити сына ея. И дуну на отрочища трижды, и призва Господа, и рече: Господи Боже мой, да возвратится убо душа отрочища сего вонь, и бысть тако. И возопи отрочищ, и сведе его с горницы в дом, и даде его матери его. И рече Илия: виждь, жив есть сын твой. И рече жена ко Илии: се уразумех, яко человек Божий еси ты, и глагол Господень во устех твоих истинен."},
  {"id": "cu-str-0603", "section": "service", "who": "reader", "text": "Пророчества Исаиина чтение: [Гл. 61, ст. 10 – 11. Гл. 62, ст. 1 – 5]"},
  {"id": "cu-str-0604", "section": "service", "who": "reader", "text": "Да возрадуется душа моя о Господе: облече бо мя в ризу спасения, и одеждою веселия [одея мя]: яко на жениха возложи на мя венец, и яко невесту украси мя красотою. И яко земля растящая цвет свой, и яко вертоград семена своя прозябает: тако возрастит Господь Господь правду, и веселие пред всеми языки. Сиона ради не умолчу, и Иерусалима ради не попущу, дондеже изыдет яко свет правда моя, и спасение мое яко светило разжжется. И узрят языцы правду твою, и царие славу твою, и прозовут тя именем новым, имже Господь наименует е. И будеши венец доброты в руце Господни, и диадима царствия в руце Бога твоего. И не прозовешися ктому оставлен, и земля твоя ктому не наречется пуста: тебе бо прозовется воля моя, и земля твоя вселенная: яко благоволи Господь в тебе, и земля твоя вкупе населится. И якоже живяй юноша с девою, тако поживут сынове твои с тобою: и будет якоже радуется жених о невесте, тако возрадуется Господь о тебе."},
  {"id": "cu-str-0605", "section": "service", "who": "reader", "text": "Бытия чтение: [Гл. 22, ст. 1 – 18]"},
  {"id": "cu-str-0606", "section": "service", "who": "reader", "text": "Бысть по глаголех сих, Бог искушаше Авраама, и рече ему: Аврааме, Аврааме. И рече: се аз. И рече: пойми сына твоего возлюбленнаго, егоже возлюбил еси Исаака, и иди на землю высоку, и вознеси его тамо во всесожжение, на едину от гор, ихже ти реку. Востав же Авраам утро, оседла осля свое, поят же с собою два отрочища, и Исаака сына своего, и растнив дрова во всесожжение, востав иде, и прииде на место, еже рече ему Бог, в третий день. И воззрев Авраам очима своима, виде место издалече. И рече Авраам отроком своим: сядите зде со ослятем: аз же и детищ пойдем до онде, и поклонившеся возвратимся к вам. Взя же Авраам дрова всесожжения, и возложи на Исаака сына своего: взя же в руки и огнь, и нож, и идоста оба вкупе. Рече же Исаак ко Аврааму отцу своему: отче. Он же рече: что есть, чадо? Рече же: се огнь и дрова, где есть овча еже во всесожжение? Рече же Авраам: Бог узрит Себе овча во всесожжение, чадо. Шедше же оба вкупе, приидоста на место, еже рече ему Бог: и созда тамо Авраам жертвенник, и возложи дрова: и связав Исаака сына своего, возложи его на жертвенник верху дров. И простре Авраам руку свою взяти нож, заклати сына своего. И воззва и Ангел Господень с небесе, и рече: Аврааме, Аврааме. Он же рече: се аз. И рече: да не возложиши руки твоея на отрочища, ниже да сотвориши ему что: ныне бо познах, яко боишися ты Бога, и не пощадел еси сына твоего возлюбленнаго Мене ради. И воззрев Авраам очима своима виде, и се овен един держимый рогама в саде савек: и иде Авраам, и взя овна, и вознесе его во всесожжение вместо Исаака сына своего. И нарече Авраам имя месту тому, Господь виде: да рекут днесь, на горе Господь явися. И воззва Ангел Господень Авраама вторицею с небесе, глаголя: Мною Самем кляхся, глаголет Господь, егоже ради сотворил еси глагол сей, и не пощадел еси сына твоего возлюбленнаго Мене ради: воистинну благословя благословлю тя, и умножая умножу семя твое, яко звезды небесныя, и яко песок вскрай моря: и наследит семя твое грады супостатов. И благословятся о семени твоем вси языцы земнии, занеже послушал еси гласа Моего."},
  {"id": "cu-str-0607", "section": "service", "who": "reader", "text": "Пророчества Исаиина чтение: [Гл. 61, ст. 1 – 9]"},
  {"id": "cu-str-0608", "section": "service", "who": "reader", "text": "Дух Господень на Мне, егоже ради помаза Мя, благовестити нищим, посла Мя, исцелити сокрушенныя сердцем, проповедати пленником отпущение, и слепым прозрение. Нарещи лето Господне приятно, и день воздаяния, утешити вся плачущия. Дати плачущим Сиона славу вместо пепела, помазание веселия плачущим, украшение славы вместо духа уныния, и нарекутся родове правды, насаждение Господне в славу. И созиждут пустыни вечныя, запустевшия прежде воздвигнут, и обновят грады пустыя, опустошенныя в роды. И приидут инороднии, пасущии овцы твоя, и иноплеменницы оратели, и виноградари ваши. Вы же священницы Господни наречетеся, служителие Бога вашего, речется вам: крепость язык снесте, и в богатстве их чудни будете. Сице землю свою вторицею наследят, и веселие вечное над главою их. Аз бо есмь Господь любяй правду, и ненавидяй грабления от неправды: и дам труд их праведником, и завет вечен завещаю им. И познается во языцех семя их, и внуцы их посреди людей: всяк видяй я познает я, яко сии суть семя благословенное от Бога и радостию возрадуются о Господе."},
  {"id": "cu-str-0609", "section": "service", "who": "reader", "text": "Царств четвертых чтение: [Гл. 4, ст. 8 – 37]"},
  {"id": "cu-str-0610", "section": "service", "who": "reader", "text": "Бысть во един день, и прейде Елиссей в Соман, и ту жена велия, и удержа его снести хлеба. И бысть ему входити, и исходити множицею, и уклоняшеся тамо ясти хлеба. И рече жена к мужу своему: се ныне разумех, яко человек Божий свят сей мимо ходит нас присно. Сотворим убо ему горницу, место мало, и поставим ему тамо одр, и трапезу, и престол, и свещник: и будет внегда входити ему к нам, и уклоняется тамо. И бысть во един день, и вниде тамо, и уклонися в горницу, и спа тамо. И рече ко Гиезию отрочищу своему: призови ми соманитяныню сию. И призва ю, и ста пред ним. И рече ему: рцы убо ей, се удивила еси нас всем попечением сим: что подобает сотворити тебе? Аще есть тебе слово к царю, или ко князю силы? Она же рече: [несть.] посреде людей моих аз есмь живущи. И рече ко Гиезию: что подобает сотворити ей? И рече Гиезий отрочищ его: воистинну сына несть у нея, и муж ея стар. И рече, призови ю. И призва ю, и ста при дверех. И рече Елиссей к ней: во время сие, якоже час сей, живущи ты зачнеши сына. Она же рече: ни, господине, не солжи рабе твоей. И зачат во чреве жена, и роди сына во время сие, якоже час сей живущи, якоже глагола к ней Елиссей."},
  {"id": "cu-str-0611", "section": "service", "who": "reader", "text": "И возмужа отрочищ: и бысть, егда изыде ко отцу своему, к жнущим. И рече ко отцу своему: глава моя, глава моя [болит]. И рече ко отроку: неси его к матери его. И несе его к матери его и лежаше на колену ея до полудне, и умре. И вознесе его, и положи его на одре человека Божия: и затвори его, и изыде, и призва мужа своего, и рече ему: посли ми убо единаго от отрок, и едино от ослят, и теку до человека Божия, и возвращуся. И рече: что яко ты идеши к нему днесь? Не нов месяц, ниже суббота. Она же рече: мир. И оседла осля, и рече ко отрочищу своему: веди, и иди, да не удержиши мене, еже всести, якоже реку тебе. Гряди, и иди, и прииди к человеку Божию на гору Кармильскую. И иде, и прииде до человека Божия в гору Кармильскую."},
  {"id": "cu-str-0612", "section": "service", "who": "reader", "text": "И бысть яко виде ю Елиссей грядущую, и рече к Гиезию отрочищу своему: се убо соманитяныня оная. Ныне тецы в сретение ея, и речеши ей: мир ли тебе? И тече во сретение ей, и рече ей: мир ли тебе; мир ли мужу твоему; мир ли отрочищу твоему? Она же рече: мир. И прииде к Елиссею на гору, и ятся за нозе его: и приближися Гиезий отринути ю. И рече Елиссей: остави ю, яко душа ея болезненна в ней, и Господь укры от мене, и не возвести мне. Она же рече: еда просих сына у господина моего, яко рекох: не прельсти мене? И рече Елиссей ко Гиезию: препояши чресла твоя, и возми жезл мой в руце твои, и иди, яко аще обрящеши мужа, да не благословиши его, и аще благословит тя муж, не отвещай ему: и возложи жезл мой на лице отрочища. И рече мати отрочища: жив Господь, и жива душа твоя, аще оставлю тебе. И воста Елиссей, и иде вслед ея. И Гиезий иде пред нею, и возложи жезл на лице отрочища, и не бе гласа, и не бе слышания. И возвратися в сретение его, и поведа ему, глаголя: не воста отрочищ."},
  {"id": "cu-str-0613", "section": "service", "who": "reader", "text": "И вниде Елиссей в храмину, и се отрочищ умерый положен на одре его. И вниде Елиссей в дом, и затвори дверь за двою собою, и помолися Господу. И взыде, и ляже на отрочищи, и положи уста своя на устех его, и очи свои на очи его, и руце свои на руце его, и плесне свои на плесну его: и слячеся над ним, и дуну на него, и согреяся плоть отрочища. И обратися, и походи в храмине сюду и сюду: и взыде и слячеся над отрочищем седмижды, и отверзе отрочищ очи свои. И возопи Елиссей ко Гиезию, и рече: призови ми соманитяныню сию. И призва ю, и вниде к нему. И рече Елиссей: приими сына твоего. И вниде жена, и паде на ногу его, и поклонися ему до земли, и прият сына своего, и изыде."},
  {"id": "cu-str-0614", "section": "service", "who": "reader", "text": "Пророчества Исаиина чтение: [Гл. 63, ст. 11 – 19. Гл. 64, ст. 1 – 5]"},
  {"id": "cu-str-0615", "section": "service", "who": "reader", "text": "Тако глаголет Господь: где возведый от земли пастыря овец своих? Где есть вложивый в них Духа Святаго? Возведшая десницею Моисеа, мышца славы Его раздели воду пред Лицем Его, сотворити Ему имя вечно. Проведе их сквозе бездну, якоже коня сквозе пустыню, и не утрудишася, и яко скоты по полю, и сниде Дух от Господа, и настави их. Тако провел еси люди Твоя, сотворити Тебе Самому имя славно. Обратися, Господи, от небесе, и виждь от дому святаго Твоего и славы Твоея: где есть ревность Твоя и крепость Твоя? Где есть множество милости Твоея, и щедрот Твоих, яко терпел еси нам? Ты бо еси Отец наш, понеже Авраам не уведе нас, и Израиль не позна нас, но Ты Господи, Отец наш, избави ны, исперва имя Твое на нас есть. Что уклонил еси нас, Господи, от пути Твоего, и ожесточил еси сердца наша еже не боятися Тебе? Обратися ради раб Твоих, ради племен достояния Твоего, да [поне] мало наследим горы святыя Твоея. Противницы наши попраша святыню Твою. Быхом яко исперва, егда не владел еси нами, ниже бе нареченное имя Твое на нас. Аще отверзеши небо, трепет приимут от Тебе горы, и растают. Яко тает воск от лица огня и попалит огнь супостаты, и явлено будет имя Твое в сопротивных Твоих: от Лица Твоего языцы возмятутся. Егда сотвориши славная, трепет приимут от Тебе горы. От века не слышах, ниже очи наши видеша Бога, разве Тебе, и дела Твоя, яже сотвориши ждущим милости. Милость бо срящет творящих правду, и пути Твоя помянутся."},
  {"id": "cu-str-0616", "section": "service", "who": "reader", "text": "Пророчества Иеремиина чтение: [Гл. 31, ст. 31 – 34]"},
  {"id": "cu-str-0617", "section": "service", "who": "reader", "text": "Тако глаголет Господь: се дние грядут, и завещаю дому Израилеву и дому Иудину завет нов. Не по завету, егоже завещах отцем их, в день, воньже емшу Ми за руку их, извести я от земли Египетския: яко тии не пребыша в завете Моем, и Аз небрегох их, глаголет Господь. Яко сей завет, егоже завещаю дому Израилеву по днех онех, глаголет Господь: дая законы Моя в мысли их, и на сердцах их напишу я, и буду им в Бога, и тии будут Ми в люди. И не научит кийждо ближняго своего, и кийждо брата своего, глаголя: познай Господа: яко вси познают Мя от мала даже и до великаго их: яко милостив буду неправдам их, и грехов их не помяну ктому."},
  {"id": "cu-str-0618", "section": "service", "who": "reader", "text": "Пророчества Даниилова чтение: [Гл. 3, ст. 1 – 88]"},
  {"id": "cu-str-0619", "section": "service", "who": "reader", "text": "В лето осмонадесятое Навуходоносор царь сотвори тело злато, высота его лактей шестидесяти, и широта его лактей шести: и постави е на поли Деире, во стране Вавилонстей. И посла [Навуходоносор царь] собрати ипаты, и воеводы, и местоначальники, вожди же и мучители, и сущия на властех, и вся князи стран, приити на обновление кумира, егоже постави Навуходоносор царь. И собрашася местоначальницы, ипаты, воеводы, вожди, мучители велицыи, иже над властьми, и вси начальницы стран на обновление тела, еже постави Навуходоносор царь: и сташа пред телом, еже постави Навуходоносор царь. И проповедник вопияше с крепостию: вам глаголется, народи, людие, племена, языцы. Воньже час аще услышите глас трубы, свирели же и гусли, самвики же и псалтири, и согласия, и всякаго рода мусикийска, падающе покланяйтеся телу златому, еже постави Навуходоносор царь. И иже аще не пад поклонится, в той час ввержен будет в пещь огнем горящую. И бысть егда услышаша людие глас трубы, свирели же и гусли, самвики же и псалтири, и согласия, и всякаго рода мусикийскаго, падающе вси людие, племена, языцы, покланяхуся телу златому, еже постави Навуходоносор царь."},
  {"id": "cu-str-0620", "section": "service", "who": "reader", "text": "Тогда приступиша мужие халдейстии и оболгаша иудеев, отвещавше реша Навуходоносору цареви: царю, во веки живи. Ты, царю, положил еси повеление, да всяк человек, иже аще услышит глас трубы, свирели же и гусли, самвики же и псалтири, и согласия, и всякаго рода мусикийска, и не пад поклонится телу златому, ввержен будет в пещь огнем горящую. Суть убо мужи Иудее, ихже поставил еси над делы страны Вавилонския, Седрах, Мисах и Авденаго, иже не послушаша заповеди твоея, царю, и богом твоим не служат, и телу златому, еже поставил еси, не покланяются."},
  {"id": "cu-str-0621", "section": "service", "who": "reader", "text": "Тогда Навуходоносор в ярости и гневе рече привести Седраха, Мисаха и Авденаго: и приведени быша пред царя. И отвеща Навуходоносор, и рече им: аще воистинну, Седрах, Мисах и Авденаго, богом моим не служите, и телу златому, еже поставих, не покланяетеся? Ныне убо, аще есте готови, да егда услышите глас трубы, свирели же и гусли, самвики же и псалтири, и согласия, и всякаго рода мусикийскаго, падше поклонитеся телу златому, еже сотворих: аще же не поклонитеся, в той час ввержени будете в пещь огнем горящую: и кто есть бог, иже измет вы из руки моея?"},
  {"id": "cu-str-0622", "section": "service", "who": "reader", "text": "И отвещаша Седрах, Мисах и Авденаго, глаголюще царю Навуходоносору: не требе нам о глаголе сем отвещати тебе. Есть бо Бог наш на Небесех, Емуже мы служим, силен изъяти нас от пещи огнем горящия и от руку твоею избавити нас, царю. Аще ли ни, ведомо да будет тебе, царю, яко богом твоим не служим, и телу златому, еже поставил еси, не кланяемся."},
  {"id": "cu-str-0623", "section": "service", "who": "reader", "text": "Тогда Навуходоносор исполнися ярости, и зрак лица его изменися на Седраха, Мисаха и Авденаго, и рече: разжжите пещь седмерицею, дондеже до конца разгорится. И мужем сильным крепостию рече: оковавше Седраха, Мисаха и Авденаго, вверзите в пещь огнем горящую. Тогда мужие онии оковани быша с гащами своими, и покрывалы, и сапогми, и со одеждами своими, и ввержени быша посреде пещи огнем горящия. Понеже глагол царев превозможе, и пещь разжжена бысть преизлишше: и мужей оных, иже ввергоша Седраха, Мисаха и Авденаго, уби пламень огненный. И мужие тии трие, Седрах, Мисах и Авденаго, падоша посреде пещи огнем горящия оковани, и хождаху посреде пламене поюще Бога, и благословяще Господа."},
  {"id": "cu-str-0624", "section": "service", "who": "reader", "text": "И став с ними Азариа помолися сице, и отверз уста своя посреде огня, и рече:"},
  {"id": "cu-str-0625", "section": "service", "who": "reader", "text": "Благословен еси, Господи Боже отец наших, хвально и прославлено имя Твое во веки."},
  {"id": "cu-str-0626", "section": "service", "who": "reader", "text": "Яко праведен еси о всех, яже сотворил еси нам, и вся дела Твоя истинна, и прави путие Твои, и вси суди Твои истинни."},
  {"id": "cu-str-0627", "section": "service", "who": "reader", "text": "И судьбы истинны сотворил еси по всем, яже навел еси на ны, и на град святый отец наших Иерусалим: яко истиною и судом навел еси сия вся на ны грех ради наших."},
  {"id": "cu-str-0628", "section": "service", "who": "reader", "text": "Яко согрешихом и беззаконновахом отступивше от Тебе, и прегрешихом во всех. И заповедей Твоих не послушахом, ниже соблюдохом, ниже сотворихом, якоже заповедал еси нам, да благо нам будет."},
  {"id": "cu-str-0629", "section": "service", "who": "reader", "text": "И вся, елика сотворил еси нам, и вся, елика навел еси на ны, истинным судом сотворил еси. И предал еси нас в руки врагов беззаконных, мерзких отступников, и царю неправедну, и лукавнейшу паче всея земли."},
  {"id": "cu-str-0630", "section": "service", "who": "reader", "text": "И ныне несть нам отверзсти уст, студ и поношение быхом рабом Твоим, и чтущим Тя."},
  {"id": "cu-str-0631", "section": "service", "who": "reader", "text": "Не предаждь убо нас до конца имене Твоего ради, и не разори завета Твоего. И не отстави милости Твоея от нас, Авраама ради возлюбленнаго от Тебе, и за Исаака раба Твоего, и Израиля святаго Твоего, имже глаголал еси умножити семя их, яко звезды небесныя, и яко песок вскрай моря."},
  {"id": "cu-str-0632", "section": "service", "who": "reader", "text": "Яко Владыко, умалихомся паче всех язык, и есмы смирени по всей земли днесь грех ради наших."},
  {"id": "cu-str-0633", "section": "service", "who": "reader", "text": "И несть во время сие князя, и пророка, и вожда, ниже всесожжения, ниже жертвы, ниже приношения, ниже кадила, ни места, еже пожрети пред Тобою и обрести милость,"},
  {"id": "cu-str-0634", "section": "service", "who": "reader", "text": "но душею сокрушенною, и духом смиренным, да прияты будем. Яко во всесожжениих овних и юнчих, и яко во тмах агнец тучных, тако да будет жертва наша пред Тобою днесь, и да совершится по Тебе, яко несть студа уповающим на Тя."},
  {"id": "cu-str-0635", "section": "service", "who": "reader", "text": "И ныне возследуем всем сердцем, и боимся Тебе, и ищем Лица Твоего."},
  {"id": "cu-str-0636", "section": "service", "who": "reader", "text": "Не посрами нас, но сотвори с нами по кротости Твоей, и по множеству милости Твоея."},
  {"id": "cu-str-0637", "section": "service", "who": "reader", "text": "И изми нас по чудесем Твоим, и даждь славу имени Твоему, Господи."},
  {"id": "cu-str-0638", "section": "service", "who": "reader", "text": "И да посрамятся вси являющии рабом Твоим злая, и да постыдятся от всякия силы, и крепость их да сокрушится."},
  {"id": "cu-str-0639", "section": "service", "who": "reader", "text": "И да разумеют, яко Ты еси Господь Бог Един, и славен по всей вселенной."},
  {"id": "cu-str-0640", "section": "service", "who": "reader", "text": "И не престаша, ввергшии их, слуги царевы жгуще пещь наффою, и смолою, и изгребми, и хврастием. И разливашеся пламень над пещию на лакти четыредесять девять. И обыде и пожже, ихже обрете окрест пещи халдейския. Ангел же Господень сниде купно с сущими со Азариею в пещь. И отрясе пламень огненный от пещи, и сотвори среднее пещи яко дух росы шумящь: и не прикоснуся их отнюдь огнь, и не оскорби, ниже стужи им. Тогда тии трие яко едиными усты пояху, и благословляху, и славляху Бога в пещи, глаголюще:"},
  {"id": "cu-str-0641", "section": "service", "who": "reader", "text": "Благословен еси, Господи Боже отец наших, и препетый и превозносимый во веки; и благословено имя славы Твоея святое, и препетое и превозносимое во веки."},
  {"id": "cu-str-0642", "section": "service", "who": "reader", "text": "Благословен еси в храме святыя славы Твоея, и препетый и превозносимый во веки."},
  {"id": "cu-str-0643", "section": "service", "who": "reader", "text": "Благословен еси видяй бездны, седяй на Херувимех, и препетый и превозносимый во веки."},
  {"id": "cu-str-0644", "section": "service", "who": "reader", "text": "Благословен еси на престоле славы Царствия Твоего, и препетый и превозносимый во веки."},
  {"id": "cu-str-0645", "section": "service", "who": "reader", "text": "Благословен еси на тверди небесней, и препетый и превозносимый во веки."},
  {"id": "cu-str-0646", "section": "service", "who": "reader", "text": "Востаем зде и поем:"},
  {"id": "cu-str-0647", "section": "service", "who": "choir", "text": "Господа пойте и превозносите во вся веки."},
  {"id": "cu-str-0648", "section": "service", "who": "rubric", "text": "Чтец же глаголет стихи:"},
  {"id": "cu-str-0649", "section": "service", "who": "reader", "text": "Благословите, вся дела Господня, И мы:"},
  {"id": "cu-str-0650", "section": "service", "who": "reader", "text": "Господа пойте и превозносите Его во веки."},
  {"id": "cu-str-0651", "section": "service", "who": "choir", "text": "Благословите Ангели Господни,"},
  {"id": "cu-str-0652", "section": "service", "who": "choir", "text": "Господа пойте и превозносите Его во веки."},
  {"id": "cu-str-0653", "section": "service", "who": "choir", "text": "Благословите небеса,"},
  {"id": "cu-str-0654", "section": "service", "who": "choir", "text": "Господа пойте и превозносите Его во веки."},
  {"id": "cu-str-0655", "section": "service", "who": "choir", "text": "Благословите воды вся, яже превыше небес,"},
  {"id": "cu-str-0656", "section": "service", "who": "choir", "text": "Господа пойте и превозносите Его во веки."},
  {"id": "cu-str-0657", "section": "service", "who": "choir", "text": "Благословите вся силы Господни,"},
  {"id": "cu-str-0658", "section": "service", "who": "choir", "text": "Господа пойте и превозносите Его во веки."},
  {"id": "cu-str-0659", "section": "service", "who": "choir", "text": "Благословите солнце и луна,"},
  {"id": "cu-str-0660", "section": "service", "who": "choir", "text": "Господа пойте и превозносите Его во веки."},
  {"id": "cu-str-0661", "section": "service", "who": "choir", "text": "Благословите звезды небесныя,"},
  {"id": "cu-str-0662", "section": "service", "who": "choir", "text": "Господа пойте и превозносите Его во веки."},
  {"id": "cu-str-0663", "section": "service", "who": "choir", "text": "Благословите всяк дождь и роса,"},
  {"id": "cu-str-0664", "section": "service", "who": "choir", "text": "Господа пойте и превозносите Его во веки."},
  {"id": "cu-str-0665", "section": "service", "who": "choir", "text": "Благословите вси дуси,"},
  {"id": "cu-str-0666", "section": "service", "who": "choir", "text": "Господа пойте и превозносите Его во веки."},
  {"id": "cu-str-0667", "section": "service", "who": "choir", "text": "Благословите огнь и вар,"},
  {"id": "cu-str-0668", "section": "service", "who": "choir", "text": "Господа пойте и превозносите Его во веки."},
  {"id": "cu-str-0669", "section": "service", "who": "choir", "text": "Благословите студь и зной,"},
  {"id": "cu-str-0670", "section": "service", "who": "choir", "text": "Господа пойте и превозносите Его во веки."},
  {"id": "cu-str-0671", "section": "service", "who": "choir", "text": "Благословите росы и иней,"},
  {"id": "cu-str-0672", "section": "service", "who": "choir", "text": "Господа пойте и превозносите Его во веки."},
  {"id": "cu-str-0673", "section": "service", "who": "choir", "text": "Благословите лед и мраз,"},
  {"id": "cu-str-0674", "section": "service", "who": "choir", "text": "Господа пойте и превозносите Его во веки."},
  {"id": "cu-str-0675", "section": "service", "who": "choir", "text": "Благословите сланы и снези,"},
  {"id": "cu-str-0676", "section": "service", "who": "choir", "text": "Господа пойте и превозносите Его во веки."},
  {"id": "cu-str-0677", "section": "service", "who": "choir", "text": "Благословите нощи и дние,"},
  {"id": "cu-str-0678", "section": "service", "who": "choir", "text": "Господа пойте и превозносите Его во веки."},
  {"id": "cu-str-0679", "section": "service", "who": "choir", "text": "Благословите свет и тьма,"},
  {"id": "cu-str-0680", "section": "service", "who": "choir", "text": "Господа пойте и превозносите Его во веки."},
  {"id": "cu-str-0681", "section": "service", "who": "choir", "text": "Благословите молния и облацы,"},
  {"id": "cu-str-0682", "section": "service", "who": "choir", "text": "Господа пойте и превозносите Его во веки."},
  {"id": "cu-str-0683", "section": "service", "who": "choir", "text": "Да благословит земля,"},
  {"id": "cu-str-0684", "section": "service", "who": "choir", "text": "Господа да поет и превозносит Его во веки."},
  {"id": "cu-str-0685", "section": "service", "who": "choir", "text": "Благословите горы и холми,"},
  {"id": "cu-str-0686", "section": "service", "who": "choir", "text": "Господа пойте и превозносите Его во веки."},
  {"id": "cu-str-0687", "section": "service", "who": "choir", "text": "Благословите вся прозябающая на земли,"},
  {"id": "cu-str-0688", "section": "service", "who": "choir", "text": "Господа пойте и превозносите Его во веки."},
  {"id": "cu-str-0689", "section": "service", "who": "choir", "text": "Благословите источницы,"},
  {"id": "cu-str-0690", "section": "service", "who": "choir", "text": "Господа пойте и превозносите Его во веки."},
  {"id": "cu-str-0691", "section": "service", "who": "choir", "text": "Благословите моря и реки,"},
  {"id": "cu-str-0692", "section": "service", "who": "choir", "text": "Господа пойте и превозносите Его во веки."},
  {"id": "cu-str-0693", "section": "service", "who": "choir", "text": "Благословите кити и вся движущаяся в водах,"},
  {"id": "cu-str-0694", "section": "service", "who": "choir", "text": "Господа пойте и превозносите Его во веки."},
  {"id": "cu-str-0695", "section": "service", "who": "choir", "text": "Благословите вся птицы небесныя,"},
  {"id": "cu-str-0696", "section": "service", "who": "choir", "text": "Господа пойте и превозносите Его во веки."},
  {"id": "cu-str-0697", "section": "service", "who": "choir", "text": "Благословите зверие и вси скоти,"},
  {"id": "cu-str-0698", "section": "service", "who": "choir", "text": "Господа пойте и превозносите Его во веки."},
  {"id": "cu-str-0699", "section": "service", "who": "choir", "text": "Благословите сынове человечестии,"},
  {"id": "cu-str-0700", "section": "service", "who": "choir", "text": "Господа пойте и превозносите Его во веки."},
  {"id": "cu-str-0701", "section": "service", "who": "choir", "text": "Да благословит Израиль,"},
  {"id": "cu-str-0702", "section": "service", "who": "choir", "text": "Господа пойте и превозносите Его во веки."},
  {"id": "cu-str-0703", "section": "service", "who": "choir", "text": "Благословите иереи Господни,"},
  {"id": "cu-str-0704", "section": "service", "who": "choir", "text": "Господа пойте и превозносите Его во веки."},
  {"id": "cu-str-0705", "section": "service", "who": "choir", "text": "Благословите раби Господни,"},
  {"id": "cu-str-0706", "section": "service", "who": "choir", "text": "Господа пойте и превозносите Его во веки."},
  {"id": "cu-str-0707", "section": "service", "who": "choir", "text": "Благословите дуси и души праведных,"},
  {"id": "cu-str-0708", "section": "service", "who": "choir", "text": "Господа пойте и превозносите Его во веки."},
  {"id": "cu-str-0709", "section": "service", "who": "choir", "text": "Благословите преподобнии и смиреннии сердцем,"},
  {"id": "cu-str-0710", "section": "service", "who": "choir", "text": "Господа пойте и превозносите Его во веки."},
  {"id": "cu-str-0711", "section": "service", "who": "choir", "text": "Благословите Анания, Азариа и Мисаил,"},
  {"id": "cu-str-0712", "section": "service", "who": "choir", "text": "Господа пойте и превозносите Его во веки."},
  {"id": "cu-str-0713", "section": "service", "who": "choir", "text": "Благословите Апостоли, пророцы и мученицы Господни,"},
  {"id": "cu-str-0714", "section": "service", "who": "choir", "text": "Господа пойте и превозносите Его во веки."},
  {"id": "cu-str-0715", "section": "service", "who": "choir", "text": "Благословим Отца, и Сына, и Святаго Духа,"},
  {"id": "cu-str-0716", "section": "service", "who": "choir", "text": "Господа поем и превозносим Его во веки."},
  {"id": "cu-str-0717", "section": "service", "who": "choir", "text": "И ныне и присно, и во веки веков, аминь."},
  {"id": "cu-str-0718", "section": "service", "who": "choir", "text": "Господа пойте и превозносите Его во веки."},
  {"id": "cu-str-0719", "section": "service", "who": "reader", "text": "Хвалим, благословим, покланяемся Господеви,"},
  {"id": "cu-str-0720", "section": "service", "who": "choir", "text": "Поюще и превозносяще во вся веки."},
  {"id": "cu-str-0721", "section": "service", "who": "rubric", "text": "Таже ектения малая."},
  {"id": "cu-str-0722", "section": "service", "who": "choir", "text": "Вместо же Трисвятаго:"},
  {"id": "cu-str-0723", "section": "service", "who": "choir", "text": "Елицы во Христа крестистеся, / во Христа облекостеся. Аллилуия. (3)"},
  {"id": "cu-str-0724", "section": "service", "who": "choir", "text": "Прокимен, глас 8:"},
  {"id": "cu-str-0725", "section": "service", "who": "choir", "text": "Вся земля да поклонится Тебе, и поет Тебе, / да поет же имени Твоему, Вышний. Стих:"},
  {"id": "cu-str-0726", "section": "service", "who": "choir", "text": "Воскликните Господеви вся земля, пойте же имени Его."},
  {"id": "cu-str-0727", "section": "service", "who": "choir", "text": "Апостол к Римлянам, зачало 91:"},
  {"id": "cu-str-0728", "section": "service", "who": "choir", "text": "Братие, елицы во Христа Иисуса крестихомся, в смерть Его крестихомся. Спогребохомся убо Ему крещением в смерть: да якоже воста Христос от мертвых славою Отчею, тако и мы во обновлении жизни ходити начнем. Аще бо сообразни быхом подобию смерти Его, то и воскресению будем. Сие ведяще, яко ветхий наш человек с Ним распятся, да упразднится тело греховное, яко ктому не работати нам греху. Умерый бо, оправдися от греха. Аще ли умрохом со Христом, веруем, яко и живи будем с Ним: Ведяще, яко Христос воста от мертвых, ктому уже не умирает, смерть Ему ктому не обладает. Еже бо умре, греху умре единою, а еже живет, Богови живет. Такожде и вы помышляйте себе: мертвым убо быти греху, живым же Богови, о Христе Иисусе, Господе нашем."},
  {"id": "cu-str-0729", "section": "service", "who": "rubric", "text": "Аллилуиа и псалом Давидов не глаголется: но по еже реши иерею:"},
  {"id": "cu-str-0730", "section": "service", "who": "choir", "text": "Мир ти,"},
  {"id": "cu-str-0731", "section": "service", "who": "rubric", "text": "абие чтец глаголет, вместо аллилуиа, во глас 7:"},
  {"id": "cu-str-0732", "section": "service", "who": "reader", "text": "Воскресни, Боже, суди земли, яко Ты наследиши во всех языцех."},
  {"id": "cu-str-0733", "section": "service", "who": "rubric", "text": "И певцы поют тожде."},
  {"id": "cu-str-0734", "section": "service", "who": "rubric", "text": "И чтец, стих:"},
  {"id": "cu-str-0735", "section": "service", "who": "reader", "text": "Бог ста в сонме богов, посреде же боги разсудит. Стих:"},
  {"id": "cu-str-0736", "section": "service", "who": "reader", "text": "Доколе судите неправду, и лица грешников приемлете? Стих:"},
  {"id": "cu-str-0737", "section": "service", "who": "reader", "text": "Судите сиру и убогу, смиренна и нища оправдайте. Стих:"},
  {"id": "cu-str-0738", "section": "service", "who": "reader", "text": "Измите нища и убога, из руки грешничи избавите его. Стих:"},
  {"id": "cu-str-0739", "section": "service", "who": "reader", "text": "Не познаша, ниже уразумеша, во тьме ходят. Стих:"},
  {"id": "cu-str-0740", "section": "service", "who": "reader", "text": "Да подвижатся вся основания земли. Аз рех: бози есте, и сынове Вышняго вси. Вы же яко человецы умираете, и яко един от князей падаете. И паки:"},
  {"id": "cu-str-0741", "section": "service", "who": "reader", "text": "Воскресни, Боже, суди земли, яко Ты наследиши во всех языцех. Егда же поют:"},
  {"id": "cu-str-0742", "section": "service", "who": "reader", "text": "Воскресни, Боже, суди земли,"},
  {"id": "cu-str-0743", "section": "service", "who": "rubric", "text": "тогда иереи и диакони извлачаются от черных одежд и облачаются в белыя."},
  {"id": "cu-str-0744", "section": "service", "who": "rubric", "text": "И по чину Божественная литургиа Великаго Василиа."},
  {"id": "cu-str-0745", "section": "service", "who": "choir", "text": "Евангелие от Матфеа, зачало 115:"},
  {"id": "cu-str-0746", "section": "service", "who": "choir", "text": "В вечер субботный, свитающи во едину от суббот, прииде Мария Магдалина, и другая Мария, видети гроб. И се трус бысть велий: Ангел бо Господень сшед с небесе, приступль отвали камень от дверий гроба, и седяше на нем. Бе же зрак его яко молния, и одеяние его бело яко снег. От страха же его сотрясошася стрегущии, и быша яко мертви. Отвещав же Ангел, рече женам: не бойтеся вы, вем бо яко Иисуса распятаго ищете. Несть зде: воста бо, якоже рече. Приидите, видите место, идеже лежа Господь. И скоро шедше рцыте учеником Его, яко воста от мертвых; и се варяет вы в Галилеи: тамо Его узрите: се рех вам. И изшедше скоро от гроба, со страхом и радостию велиею, текосте возвестити учеником Его. Якоже идясте возвестити учеником Его, и се Иисус срете я, глаголя: радуйтеся. Оне же приступльше, ястеся за нозе Его, и поклонистеся Ему. Тогда глагола има Иисус: не бойтеся, идите, возвестите братии моей, да идут в Галилею, и ту мя видят. Идущема же има, се нецыи от кустодиа пришедше во град, возвестиша архиереом вся бывшая. И собравшеся со старцы, совет сотвориша, сребреники довольны даша воином, глаголюще: рцыте, яко ученицы Его нощию пришедше украдоша Его, нам спящим. И аще сие услышано будет у игемона, мы утолим его, и вас безпечальны сотворим. Они же приемше сребреники, сотвориша, якоже научени быша. И промчеся слово сие во иудеех, даже до сего дне. Единии же надесяте ученицы идоша в Галилею, в гору, аможе повеле им Иисус. И видевше Его поклонишася Ему: ови же усумнешася. И приступль Иисус, рече им, глаголя: дадеся Ми всяка власть на небеси и на земли. Шедше научите вся языки, крестяще их во имя Отца, и Сына, и Святаго Духа, учаще их блюсти вся, елика заповедах вам. И се Аз с вами есмь во вся дни, до скончания века, аминь."},
  {"id": "cu-str-0747", "section": "service", "who": "choir", "text": "Вместо же Херувимския песни поется настоящий тропарь, глас 8:"},
  {"id": "cu-str-0748", "section": "service", "who": "choir", "text": "Да молчит всякая плоть человеча, / и да стоит со страхом и трепетом, / и ничтоже земное в себе да помышляет: / Царь бо царствующих, и Господь господствующих, / приходит заклатися и датися в снедь верным. / Предходят же Сему лицы Ангельстии / со всяким Началом и Властию, / многоочитии Херувими, / и шестокрилатии Серафими, / лица закрывающе, и вопиюще песнь: / аллилуиа, аллилуиа, аллилуиа."},
  {"id": "cu-str-0749", "section": "service", "who": "choir", "text": "Вместо же Достойно, ирмос:"},
  {"id": "cu-str-0750", "section": "service", "who": "choir", "text": "Не рыдай Мене, Мати, / зрящи во гробе, / Егоже во чреве без семене зачала еси Сына: / востану бо и прославлюся / и вознесу со славою непрестанно, яко Бог, / верою и любовию Тя величающия."},
  {"id": "cu-str-0751", "section": "service", "who": "choir", "text": "Причастен, глас 4:"},
  {"id": "cu-str-0752", "section": "service", "who": "choir", "text": "Воста яко спя Господь, / и воскресе спасаяй нас. Аллилуиа, трижды."},
  {"id": "cu-str-0753", "section": "service", "who": "rubric", "text": "По отпусте же дается от священника антидор, Таже бывает благословение хлеба и вина."},
  {"id": "cu-str-0754", "section": "service", "who": "deacon", "text": "Господу помолимся."},
  {"id": "cu-str-0755", "section": "service", "who": "choir", "text": "Господи, помилуй."},
  {"id": "cu-str-0756", "section": "service", "who": "priest", "text": "Господи Иисусе Христе Боже наш, благословивый пять хлебов и пять тысящ насытивый, Сам благослови и хлебы сия, пшеницу, вино и елей: и умножи сия во граде сем (или"},
  {"id": "cu-str-0757", "section": "service", "who": "priest", "text": "в веси сей , или"},
  {"id": "cu-str-0758", "section": "service", "who": "priest", "text": "во святей обители сей )"},
  {"id": "cu-str-0759", "section": "service", "who": "priest", "text": "и во всем мире Твоем: и вкушающия от них верныя освяти. Яко Ты еси благословляяй и освящаяй всяческая, Христе Боже наш, и Тебе славу возсылаем, со Безначальным Твоим Отцем, и Всесвятым и Благим и Животворящим Твоим Духом, ныне и присно и во веки веков."},
  {"id": "cu-str-0760", "section": "service", "who": "choir", "text": "Аминь."},
  {"id": "cu-str-0761", "section": "service", "who": "rubric", "text": "Отпуст Литургии:"},
  {"id": "cu-str-0762", "section": "service", "who": "choir", "text": "Христос, Истинный Бог наш:"},
  {"id": "cu-str-0763", "section": "service", "who": "choir", "text": "Иный отпуст:"},
  {"id": "cu-str-0764", "section": "service", "who": "choir", "text": "Иже нас pади и нашего pади спасения, смиpив Себе и в нашy нищетy облечеся и волею Стpасти пpетеpпе и смеpть вкyсив и во гpобе положивыйся Хpистос, Истинный Бог наш, молитвами Пpечистыя Своея Матеpе, святых славных и всехвальных Апостол, иже во святых отца нашего Василия Великаго, архиепископа Кесарии Каппадокийския, и всех святых, помилyет и спасет нас, яко Благ и Человеколюбец."},
  {"id": "cu-str-0765", "section": "service", "who": "rubric", "text": "Долженствует же екклисиарх имети опасство, да егда скончавается литургиа, будет час вторый нощи. По отпусте же не исходим из церкве, но седим на местех наших: и входит келарь, и дает братии по единому укруху хлеба и по шести смоквей или фиников, и по единому красовулю вина. Нам же возлежащим, бывает чтение великое в Деяниих святых Апостол от начала. Глаголет же чтец начало. Священник же стих: Молитвами святых апостол, Господи Иисусе Христе Боже наш, помилуй нас. И по Амине начинает чтец чести. Таже начинаем ясти. И по скончании чтения вжигает кандиловжигатель вся кандила храма, и, исходя, ударяет в клепало: и престает чтый чтение."},
  {"id": "cu-str-0766", "section": "service", "who": "choir", "text": "ПОЛУНОЩНИЦА ВО СВЯТУЮ И ВЕЛИКУЮ СУББОТУ"},
  {"id": "cu-str-0767", "section": "service", "who": "rubric", "text": "Долженствует же екклисиарх имети опасство, да егда скончавается Литургия, будет час вторый нощи. По отпусте же не исходим из церкве, но седим на местех наших: и входит келарь, и дает братии по единому укруху хлеба и по шести смоквей или фиников, и по единому красовулю вина. Нам же возлежащим, бывает чтение великое в Деяниих святых Апостол от начала. Глаголет же чтец начало. Священник же стих:"},
  {"id": "cu-str-0768", "section": "service", "who": "priest", "text": "Молитвами святых Апостол, Господи Иисусе Христе Боже наш, помилуй нас. И по"},
  {"id": "cu-str-0769", "section": "service", "who": "priest", "text": "Амине"},
  {"id": "cu-str-0770", "section": "service", "who": "rubric", "text": "начинает чтец чести. Таже начинаем ясти. И по скончании чтения вжигает кандиловжигатель вся кандила храма, и, исходя, ударяет в клепало: и престает чтый чтение."},
  {"id": "cu-str-0771", "section": "service", "who": "rubric", "text": "Благословившу же священнику, начинаем Трисвятое, и прочее."},
  {"id": "cu-str-0772", "section": "service", "who": "priest", "text": "Приидите, поклонимся,"},
  {"id": "cu-str-0773", "section": "service", "who": "rubric", "text": "трижды. Псалом 50. И канон Великия Субботы: ирмосы по дважды, тропари же на дванадесять, со стихи песней. Катавасиа, ирмос оба лика."},
  {"id": "cu-str-0774", "section": "service", "who": "choir", "text": "Глас 6. Песнь 1. Ирмос:"},
  {"id": "cu-str-0775", "section": "service", "who": "choir", "text": "Волною морскою / Скрывшаго древле, / гонителя мучителя, под землею скрыша / спасенных отроцы; / но мы, яко отроковицы, / Господеви поим, / славно бо прославися."},
  {"id": "cu-str-0776", "section": "service", "who": "choir", "text": "{Κ} Господи Боже мой, / исходное пение, и надгробную Тебе песнь воспою, / погребением Твоим жизни моея входы отверзшему, / и смертию смерть и ад умертвившему."},
  {"id": "cu-str-0777", "section": "service", "who": "choir", "text": "{Α} Горе Тя на Престоле и доле во гробе, / премирная и подземная, помышляющая Спасе мой, / зыбляхуся умерщвлением Твоим: / паче ума бо виден был еси мертв, Живоначальниче."},
  {"id": "cu-str-0778", "section": "service", "who": "choir", "text": "{Ι} Да Твоея славы вся исполниши, / сшел еси в нижняя земли: / от Тебе бо не скрыся состав мой, иже во Адаме, и погребен, / истлевша мя обновляеши, Человеколюбче."},
  {"id": "cu-str-0779", "section": "service", "who": "choir", "text": "Песнь 3. Ирмос:"},
  {"id": "cu-str-0780", "section": "service", "who": "choir", "text": "Тебе, на водах / повесившаго / всю землю неодержимо, / тварь видевши / на лобнем висима, / ужасом многим содрогашеся, / несть свят, / разве Тебе Господи, взывающи."},
  {"id": "cu-str-0781", "section": "service", "who": "choir", "text": "{Σ} Образы погребения Твоего показал еси, видения умножив. / Ныне же сокровенная Твоя богомужно уяснил еси, и сущим во аде Владыко, / несть свят, разве Тебе Господи, взывающим."},
  {"id": "cu-str-0782", "section": "service", "who": "choir", "text": "{Η} Простерл еси длани, и соединил еси древле разстоящаяся. / Одеянием же Спасе, еже в плащанице и во гробе, / окованныя разрешил еси, / несть свят, разве Тебе Господи, взывающия."},
  {"id": "cu-str-0783", "section": "service", "who": "choir", "text": "{Μ} Гробом и печатьми, Невместиме, / содержимь был еси хотением: / ибо силу Твою действы показал еси, / богодейственно поющим: / несть свят, разве Тебе Господи, Человеколюбче."},
  {"id": "cu-str-0784", "section": "service", "who": "choir", "text": "Седален, глас 1: Гроб Твой Спасе, воини стрегущии, / мертви от облистания явльшагося Ангела быша, / проповедающа женам Воскресение. / Тебе славим, тли потребителя! / Тебе припадаем, Воскресшему из гроба, / и Единому Богу нашему!"},
  {"id": "cu-str-0785", "section": "service", "who": "choir", "text": "Слава, и ныне, тойже."},
  {"id": "cu-str-0786", "section": "service", "who": "rubric", "text": "И чтение в слове святаго Епифаниа, егоже начало:"},
  {"id": "cu-str-0787", "section": "service", "who": "reader", "text": "Что сие днесь:"},
  {"id": "cu-str-0788", "section": "service", "who": "rubric", "text": "Или от словес Златоустаго: ищи я в толковании на Евангелие от Матфеа, или на Иоанна, словеса воскресная."},
  {"id": "cu-str-0789", "section": "service", "who": "reader", "text": "Песнь 4. Ирмос:"},
  {"id": "cu-str-0790", "section": "service", "who": "reader", "text": "На Кресте Твое / Божественное истощание / провидя Аввакум, / ужасся, вопияше: / Ты сильных пресекл еси / державу Блаже, / приобщаяся сущим во аде, яко Всесилен."},
  {"id": "cu-str-0791", "section": "service", "who": "choir", "text": "{Ε} Седьмый день днесь освятил еси, / егоже древле благословил еси упокоением дел: / преводиши бо всяческая и обновляеши, / субботствуя Спасе мой, и назидая."},
  {"id": "cu-str-0792", "section": "service", "who": "choir", "text": "{Ρ} Силою лучшаго, победившаго Тебе, / от плоти душа Твоя разделися, / растерзающи бо обоя узы, / смерти и ада, Слове, державою Твоею."},
  {"id": "cu-str-0793", "section": "service", "who": "choir", "text": "{Ο} Ад Слове, срет Тя огорчися, / человека зря обожена, / уязвлена ранами, и Всесильнодетеля, / страшным же зраком погибе."},
  {"id": "cu-str-0794", "section": "service", "who": "choir", "text": "Песнь 5. Ирмос:"},
  {"id": "cu-str-0795", "section": "service", "who": "choir", "text": "Богоявления Твоего Христе, / к нам милостивно бывшаго, / Исаия Свет видев Невечерний, / из нощи утреневав взываше: / воскреснут мертвии, / и востанут сущии во гробех, / и вси земнороднии возрадуются."},
  {"id": "cu-str-0796", "section": "service", "who": "choir", "text": "{Ν} Новотвориши земныя Создателю, перстен быв, / и плащаница и гроб являют еже в Тебе Слове, таинство. / Благообразный бо советник, Тебе Рождшаго совет образует, / в Тебе велелепно новотворящаго мя."},
  {"id": "cu-str-0797", "section": "service", "who": "choir", "text": "{Δ} Смертию смертное, / погребением тленное прелагаеши, / нетленно твориши бо, / боголепно безсмертно творя приятие, / плоть бо Твоя истления не виде Владыко, / ниже душа Твоя во аде страннолепно оставлена бысть."},
  {"id": "cu-str-0798", "section": "service", "who": "choir", "text": "{Ε} Из Небрачныя прошед, и прободен в ребра Содетелю мой, / из Нея соделал еси обновление Евино, Адам быв, / уснув паче естества сном естественным, / и жизнь воздвигнув от сна и тления, яко Всесилен."},
  {"id": "cu-str-0799", "section": "service", "who": "choir", "text": "Песнь 6. {Σ} Ирмос:"},
  {"id": "cu-str-0800", "section": "service", "who": "choir", "text": "Ят бысть, / но не удержан в персех китовых Иона: / Твой бо образ нося, / Страдавшаго, и погребению давшагося, / яко от чертога от зверя изыде. / Приглашаше же кустодии, / хранящии суетная и ложная, / милость сию оставили есте."},
  {"id": "cu-str-0801", "section": "service", "who": "choir", "text": "{Α} Биен был еси, но не разделился еси Слове, / еяже причастился еси плоти: / аще бо и разорися Твой храм во время страсти, / но и тако един бе состав Божества и плоти Твоея. / Во обоих бо Един еси Сын, Слово Божие, Бог и Человек."},
  {"id": "cu-str-0802", "section": "service", "who": "choir", "text": "{Β} Человекоубийственно, но не богоубийственно бысть прегрешение Адамово: / аще бо и пострада Твоея плоти перстное существо, / но Божество безстрастно пребысть, / тленное же Твое на нетление преложил еси, / и нетленныя жизни показал еси источник Воскресением."},
  {"id": "cu-str-0803", "section": "service", "who": "choir", "text": "{Β} Царствует ад, но не вечнует над родом человеческим: / Ты бо положся во гробе Державне, живоначальною дланию, / смерти ключи развергл еси, / и проповедал еси от века тамо спящим, избавление неложное / быв Спасе, мертвым первенец."},
  {"id": "cu-str-0804", "section": "service", "who": "choir", "text": "Кондак, глас 6: Бездну заключивый, мертв зрится, / и смирною и плащаницею обвився, / во гробе полагается яко смертный Безсмертный: / жены же приидоша помазати Его миром, / плачущия горько и вопиющия: / сия суббота есть преблагословенная, / в нейже Христос уснув, воскреснет тридневен. Икос:"},
  {"id": "cu-str-0805", "section": "service", "who": "choir", "text": "Содержай вся на Крест вознесеся, / и рыдает вся тварь, Того видящи нага висяща на древе, / солнце лучи сокры, и звезды отложиша свет: / земля же со многим страхом поколебася, и море побеже, / и камение распадеся, гроби же многи отверзошася, / и телеса восташа святых мужей. / Ад низу стенет, / и иудее советуют оклеветати Христово Воскресение. / Жены же взывают: / сия суббота есть преблагословенная, / в нейже Христос, уснув, воскреснет тридневен."},
  {"id": "cu-str-0806", "section": "service", "who": "rubric", "text": "Синаксарий. Таже чтение."},
  {"id": "cu-str-0807", "section": "service", "who": "choir", "text": "Песнь 7. {Α} Ирмос:"},
  {"id": "cu-str-0808", "section": "service", "who": "choir", "text": "Неизреченное чудо, / в пещи избавивый / преподобныя отроки из пламене, / во гробе мертв / бездыханен полагается, / во спасение нас поющих: / Избавителю Боже, / благословен еси."},
  {"id": "cu-str-0809", "section": "service", "who": "choir", "text": "{Τ} Уязвися ад, в сердце / прием Уязвеннаго копием в ребра, / и воздыхает огнем Божественным иждиваемь, / во спасение нас поющих: / Избавителю Боже, благословен еси."},
  {"id": "cu-str-0810", "section": "service", "who": "choir", "text": "{Ο} Богат гроб, / в себе бо приим яко спяща Содетеля, / жизни Божественное сокровище показася, / во спасение нас поющих: / Избавителю Боже, благословен еси."},
  {"id": "cu-str-0811", "section": "service", "who": "choir", "text": "{Ν} Законом умерших / еже во гробе положение, всех приемлет Жизнь, / и сего источника показует востания, / во спасение нас поющих: / Избавителю Боже, благословен еси."},
  {"id": "cu-str-0812", "section": "service", "who": "choir", "text": "{Μ} Едино бяше неразлучное, / еже во аде, и во гробе, и во Едеме, / Божество Христово, со Отцем и Духом, / во спасение нас поющих: / Избавителю Боже, благословен еси."},
  {"id": "cu-str-0813", "section": "service", "who": "choir", "text": "Песнь 8. {Ε} Ирмос:"},
  {"id": "cu-str-0814", "section": "service", "who": "choir", "text": "Ужаснися бояйся небо, / и да подвижатся основания земли: / се бо в мертвецех вменяется в вышних Живый, / и во гроб мал странноприемлется. / Егоже отроцы благословите, / священницы воспойте, / людие превозносите во вся веки."},
  {"id": "cu-str-0815", "section": "service", "who": "choir", "text": "{Λ} Разрушися Пречистый храм, / падшую же совозставляет скинию: / Адаму бо первому Вторый, Иже в вышних Живый, / сниде даже до адовых сокровищ. / Егоже отроцы благословите, / священницы воспойте, / людие превозносите во вся веки."},
  {"id": "cu-str-0816", "section": "service", "who": "choir", "text": "{Π} Преста дерзость учеников, / Аримафей же изрядствует Иосиф: / мертва бо и нага зря, над всеми Бога, / просит и погребает, зовый: / отроцы благословите, / священницы воспойте, / людие, превозносите во вся веки."},
  {"id": "cu-str-0817", "section": "service", "who": "choir", "text": "{Ω} О чудес новых! / О благости! / О неизреченнаго терпения! / Волею бо под землею печатлеется, Иже в вышних Живый, / и яко льстец, Бог оклеветается. / Егоже отроцы благословите, / священницы воспойте, / людие превозносите во вся веки."},
  {"id": "cu-str-0818", "section": "service", "who": "choir", "text": "Песнь 9. {Μ} Ирмос:"},
  {"id": "cu-str-0819", "section": "service", "who": "choir", "text": "Не рыдай Мене Мати, / зрящи во гробе, / Егоже во чреве без семене зачала еси Сына: / востану бо и прославлюся, / и вознесу со славою, непрестанно яко Бог, / верою и любовию Тя величающия."},
  {"id": "cu-str-0820", "section": "service", "who": "choir", "text": "{Ε} В страннем Твоем рождестве, / болезней избежавше паче естества, / ублажихся Безначальне Сыне: / ныне же Тя Боже мой, / бездыханна зрящи мертва, / оружием печали растерзаюся люте, / но воскресни, яко да возвеличуся."},
  {"id": "cu-str-0821", "section": "service", "who": "choir", "text": "{Γ} Земля покрывает Мя хотяща, / но устрашаются адовы вратницы, / одеяна видяще одеждею окровавленою, Мати, отмщения: / враги бо Крестом поразив яко Бог, / воскресну паки, и возвеличу Тя."},
  {"id": "cu-str-0822", "section": "service", "who": "choir", "text": "{Α} Да радуется тварь, / да веселятся вси земнороднии, / враг бо пленися ад: / с миры жены да сретают, / Адама со Евою избавляю всеродна, / и в третий день воскресну."},
  {"id": "cu-str-0823", "section": "service", "who": "rubric", "text": "По 9-й же песни Трисвятое."},
  {"id": "cu-str-0824", "section": "service", "who": "choir", "text": "И тропарь, глас 2: Егда снизшел еси к смерти, Животе безсмертный, / тогда ад умертвил еси блистанием Божества. / Егда же и умершия от преисподних воскресил еси, / вся силы небесныя взываху: / Жизнодавче Христе Боже наш, слава Тебе."},
  {"id": "cu-str-0825", "section": "service", "who": "rubric", "text": "Ектениа. И отпуст:"},
  {"id": "cu-str-0826", "section": "service", "who": "choir", "text": "Христос, Истинный Бог наш:"},
];

